screenPanels.initJs:
function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentPeriod = 30;

  // 店舗データを店舗選択に設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // KPI計算
  function calculateKPIs(salesData, forecastData, orderData) {
    const now = new Date();
    const currentMonth = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
    const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const lastMonthStr = lastMonth.getFullYear() + '-' + String(lastMonth.getMonth() + 1).padStart(2, '0');

    // 今月売上
    const currentMonthSales = salesData
      .filter(s => s.売上日 && s.売上日.startsWith(currentMonth))
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const lastMonthSales = salesData
      .filter(s => s.売上日 && s.売上日.startsWith(lastMonthStr))
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    // 予測精度（MAPE計算）
    let totalError = 0;
    let validPredictions = 0;
    forecastData.forEach(f => {
      if (f.実績数量 && f.予測数量 && f.実績数量 > 0) {
        totalError += Math.abs((f.実績数量 - f.予測数量) / f.実績数量);
        validPredictions++;
      }
    });
    const accuracy = validPredictions > 0 ? Math.max(0, 100 - (totalError / validPredictions * 100)) : 0;

    // 発注件数
    const orderCount = orderData.length;

    // 在庫アラート（仮想的に低在庫商品数を計算）
    const alertCount = Math.floor(Math.random() * 5) + 1;

    return {
      currentMonthSales,
      lastMonthSales,
      accuracy,
      orderCount,
      alertCount
    };
  }

  // KPI表示更新
  function updateKPIs(kpis) {
    container.querySelector('#kpi-sales').textContent = '¥' + kpis.currentMonthSales.toLocaleString();
    container.querySelector('#kpi-accuracy').textContent = Math.round(kpis.accuracy) + '%';
    container.querySelector('#kpi-orders').textContent = kpis.orderCount + '件';
    container.querySelector('#kpi-alerts').textContent = kpis.alertCount + '件';

    // 前月比表示
    const salesChange = kpis.lastMonthSales > 0 ? 
      ((kpis.currentMonthSales - kpis.lastMonthSales) / kpis.lastMonthSales * 100) : 0;
    container.querySelector('#kpi-sales-change').textContent = 
      (salesChange >= 0 ? '+' : '') + salesChange.toFixed(1) + '% vs 前月';
  }

  // 売上トレンドグラフ
  function renderSalesTrend(salesData) {
    const ctx = container.querySelector('#sales-trend-chart').getContext('2d');

    // 日別売上集計
    const dailySales = {};
    salesData.forEach(sale => {
      if (sale.売上日) {
        const date = sale.売上日.slice(0, 10);
        dailySales[date] = (dailySales[date] || 0) + (sale.売上金額 || 0);
      }
    });

    const sortedDates = Object.keys(dailySales).sort();
    const last30Days = sortedDates.slice(-30);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: last30Days.map(d => d.slice(5)),
        datasets: [{
          label: '売上金額',
          data: last30Days.map(d => dailySales[d] || 0),
          borderColor: '#4f9eff',
          backgroundColor: 'rgba(79, 158, 255, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });
  }

  // 予測精度グラフ
  function renderAccuracyChart(forecastData) {
    const ctx = container.querySelector('#accuracy-chart').getContext('2d');

    // 日別精度計算
    const dailyAccuracy = {};
    forecastData.forEach(f => {
      if (f.予測対象日 && f.実績数量 && f.予測数量 && f.実績数量 > 0) {
        const date = f.予測対象日.slice(0, 10);
        if (!dailyAccuracy[date]) dailyAccuracy[date] = { total: 0, count: 0 };
        const accuracy = Math.max(0, 100 - Math.abs((f.実績数量 - f.予測数量) / f.実績数量 * 100));
        dailyAccuracy[date].total += accuracy;
        dailyAccuracy[date].count++;
      }
    });

    const sortedDates = Object.keys(dailyAccuracy).sort();
    const last14Days = sortedDates.slice(-14);

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: last14Days.map(d => d.slice(5)),
        datasets: [{
          label: '予測精度(%)',
          data: last14Days.map(d => dailyAccuracy[d] ? dailyAccuracy[d].total / dailyAccuracy[d].count : 0),
          borderColor: '#00d4aa',
          backgroundColor: 'rgba(0, 212, 170, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            max: 100,
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });
  }

  // 天候影響グラフ
  function renderWeatherChart(salesData, weatherData) {
    const ctx = container.querySelector('#weather-chart').getContext('2d');

    // 天候別売上集計
    const weatherSales = {};
    salesData.forEach(sale => {
      if (sale.天候区分) {
        weatherSales[sale.天候区分] = (weatherSales[sale.天候区分] || 0) + (sale.売上金額 || 0);
      }
    });

    const weatherTypes = Object.keys(weatherSales);
    const colors = ['#4f9eff', '#00d4aa', '#ff6a00', '#ff4757', '#9c88ff'];

    new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: weatherTypes,
        datasets: [{
          data: weatherTypes.map(w => weatherSales[w]),
          backgroundColor: colors.slice(0, weatherTypes.length),
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { 
            labels: { color: '#d0e4ff' },
            position: 'bottom'
          }
        }
      }
    });
  }

  // 商品別売上ランキング
  function renderProductRanking(salesData, productData) {
    const productSales = {};
    salesData.forEach(sale => {
      if (sale.商品ID) {
        productSales[sale.商品ID] = (productSales[sale.商品ID] || 0) + (sale.売上金額 || 0);
      }
    });

    const sortedProducts = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 5);

    const rankingHtml = sortedProducts.map(([productId, sales], index) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product ? product.商品名 : `商品${productId.slice(0, 8)}`;
      return `
        <div class="ranking-item">
          <div class="ranking-rank">${index + 1}</div>
          <div class="ranking-name">${productName}</div>
          <div class="ranking-value">¥${sales.toLocaleString()}</div>
        </div>
      `;
    }).join('');

    container.querySelector('#product-ranking').innerHTML = 
      rankingHtml || '<div class="no-data">データがありません</div>';
  }

  // 発注状況更新
  function updateOrderStatus(orderData) {
    const statusCounts = { pending: 0, ordered: 0, received: 0 };
    orderData.forEach(order => {
      switch (order.発注ステータス) {
        case '未発注': statusCounts.pending++; break;
        case '発注済': statusCounts.ordered++; break;
        case '納品済': statusCounts.received++; break;
      }
    });

    container.querySelector('#status-pending').textContent = statusCounts.pending;
    container.querySelector('#status-ordered').textContent = statusCounts.ordered;
    container.querySelector('#status-received').textContent = statusCounts.received;
  }

  // イベント・季節要因表示
  function renderEvents(eventData, seasonData) {
    const now = new Date();
    const upcoming = eventData
      .filter(e => e.有効フラグ && new Date(e.開始日時) >= now)
      .sort((a, b) => new Date(a.開始日時) - new Date(b.開始日時))
      .slice(0, 3);

    const eventsHtml = upcoming.map(event => `
      <div class="event-item">
        <div>
          <div class="event-name">${event.イベント名}</div>
          <div class="event-date">${event.開始日時.slice(0, 10)}</div>
        </div>
        <div class="event-impact">${event.影響度}</div>
      </div>
    `).join('');

    container.querySelector('#event-list').innerHTML = 
      eventsHtml || '<div class="no-data">予定されたイベントはありません</div>';
  }

  // 在庫アラート表示
  function renderAlerts() {
    // サンプルアラート（実際は在庫データから計算）
    const alerts = [
      { product: '商品A', stock: 5, min: 10 },
      { product: '商品B', stock: 2, min: 15 },
      { product: '商品C', stock: 0, min: 5 }
    ];

    const alertsHtml = alerts.map(alert => `
      <div class="alert-item">
        <div>
          <div class="alert-product">${alert.product}</div>
          <div class="alert-stock">在庫: ${alert.stock}個 (最低: ${alert.min}個)</div>
        </div>
        <div class="alert-level">緊急</div>
      </div>
    `).join('');

    container.querySelector('#alert-list').innerHTML = 
      alertsHtml || '<div class="no-data">アラートはありません</div>';
  }

  // データ更新
  async function updateDashboard() {
    try {
      const [salesData, forecastData, orderData, productData, eventData, seasonData, weatherData] = await Promise.all([
        window.aivicApi.list(tables.findIndex(t => t.tableName === '売上実績データ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '需要予測結果')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '発注データ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '商品マスタ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === 'イベントデータ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '季節情報データ')),
        window.aivicApi.list(tables.findIndex(t => t.tableName === '天候データ'))
      ]);

      // 店舗フィルタリング
      const filteredSales = currentStoreId ? 
        salesData.filter(s => s.店舗ID === currentStoreId) : salesData;
      const filteredForecast = currentStoreId ? 
        forecastData.filter(f => f.店舗ID === currentStoreId) : forecastData;
      const filteredOrders = currentStoreId ? 
        orderData.filter(o => o.店舗ID === currentStoreId) : orderData;

      // 期間フィルタリング
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - currentPeriod);
      const cutoffStr = cutoffDate.toISOString().slice(0, 10);

      const periodSales = filteredSales.filter(s => s.売上日 >= cutoffStr);
      const periodForecast = filteredForecast.filter(f => f.予測対象日 >= cutoffStr);

      // 各セクション更新
      const kpis = calculateKPIs(filteredSales, filteredForecast, filteredOrders);
      updateKPIs(kpis);
      renderSalesTrend(periodSales);
      renderAccuracyChart(periodForecast);
      renderWeatherChart(periodSales, weatherData);
      renderProductRanking(periodSales, productData);
      updateOrderStatus(filteredOrders);
      renderEvents(eventData, seasonData);
      renderAlerts();

    } catch (error) {
      console.error('Dashboard update failed:', error);
      container.querySelector('#kpi-sales').textContent = 'エラー';
    }
  }

  // イベントリスナー
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    updateDashboard();
  });

  container.querySelector('#period-select').addEventListener('change', (e) => {
    currentPeriod = parseInt(e.target.value);
    updateDashboard();
  });

  // 初期化
  loadStores();
  updateDashboard();
}

function(container, apiUrl, tables) {
  let analysisData = [];
  let currentAnalysisResults = null;

  // 初期化処理
  async function initialize() {
    await loadStores();
    await loadCategories();
    await loadProducts();
    setupEventListeners();
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      stores.forEach(store => {
        const option = document.createElement('option');
        option.value = store.id;
        option.textContent = store.店舗名 || store.storeName || 'Unknown Store';
        storeSelect.appendChild(option);
      });
    }
  }

  // カテゴリデータ読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const categoryCheckboxes = container.querySelector('#category-checkboxes');
    const categories = new Set();

    if (products) {
      products.forEach(product => {
        const category = product.商品カテゴリID || product.categoryId || 'その他';
        categories.add(category);
      });

      categories.forEach(category => {
        const label = document.createElement('label');
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.value = category;
        checkbox.className = 'category-checkbox';
        label.appendChild(checkbox);
        label.appendChild(document.createTextNode(' ' + category));
        categoryCheckboxes.appendChild(label);
      });
    }
  }

  // 商品データ読み込み
  async function loadProducts() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const productSelect = container.querySelector('#comparison-products');
    if (products) {
      products.forEach(product => {
        const option = document.createElement('option');
        option.value = product.id;
        option.textContent = product.商品名 || product.productName || 'Unknown Product';
        productSelect.appendChild(option);
      });
    }
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 全選択チェックボックス
    container.querySelector('#select-all-categories').addEventListener('change', function() {
      const checkboxes = container.querySelectorAll('.category-checkbox');
      checkboxes.forEach(cb => cb.checked = this.checked);
    });

    // 分析実行ボタン
    container.querySelector('#btn-analyze').addEventListener('click', executeAnalysis);

    // CSVエクスポートボタン
    container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

    // タブ切り替え
    container.querySelectorAll('.tab-btn').forEach(btn => {
      btn.addEventListener('click', function() {
        const tabId = this.dataset.tab;
        switchTab(tabId);
      });
    });
  }

  // バリデーション
  function validateInputs() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    const selectedFactors = container.querySelectorAll('#factor-checkboxes input:checked');

    if (!startDate) {
      showError('分析期間の開始日を選択してください');
      return false;
    }

    if (!endDate) {
      showError('分析期間の終了日を選択してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日以前の日付を入力してください');
      return false;
    }

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (selectedCategories.length === 0) {
      showError('商品カテゴリを選択してください');
      return false;
    }

    if (selectedFactors.length === 0) {
      showError('分析要因を選択してください');
      return false;
    }

    return true;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 分析実行
  async function executeAnalysis() {
    if (!validateInputs()) return;

    const loadingIndicator = container.querySelector('#loading-indicator');
    const resultsDiv = container.querySelector('#analysis-results');

    loadingIndicator.classList.remove('hidden');
    resultsDiv.classList.add('hidden');

    try {
      // 売上実績データ取得
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      const weatherData = await window.aivicApi.list(4); // 天候データ
      const eventData = await window.aivicApi.list(5); // イベントデータ
      const seasonData = await window.aivicApi.list(6); // 季節情報データ

      if (!salesData || salesData.length === 0) {
        showError('選択された期間のデータが不足しているため、分析を実行できません。より長い期間を選択してください。');
        return;
      }

      // 分析処理実行
      currentAnalysisResults = performCorrelationAnalysis(salesData, weatherData, eventData, seasonData);

      // 結果表示
      displayAnalysisResults(currentAnalysisResults);

    } catch (error) {
      showError('システムエラーが発生しました。システム管理者にお問い合わせください。');
      console.error('Analysis error:', error);
    } finally {
      loadingIndicator.classList.add('hidden');
    }
  }

  // 相関分析実行
  function performCorrelationAnalysis(salesData, weatherData, eventData, seasonData) {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const storeId = container.querySelector('#store-select').value;

    // データフィルタリング
    const filteredSales = salesData.filter(sale => {
      const saleDate = new Date(sale.売上日 || sale.saleDate);
      return saleDate >= new Date(startDate) && 
             saleDate <= new Date(endDate) && 
             sale.店舗ID === storeId;
    });

    // 相関係数計算
    const correlations = [];

    // 天候との相関
    if (container.querySelector('#factor-weather').checked) {
      const tempCorrelation = calculateCorrelation(filteredSales, weatherData, 'temperature');
      const rainCorrelation = calculateCorrelation(filteredSales, weatherData, 'rainfall');
      correlations.push(
        { factor: '気温', correlation: tempCorrelation, significance: 0.05, evaluation: evaluateCorrelation(tempCorrelation) },
        { factor: '降水量', correlation: rainCorrelation, significance: 0.05, evaluation: evaluateCorrelation(rainCorrelation) }
      );
    }

    // イベントとの相関
    if (container.querySelector('#factor-event').checked) {
      const eventCorrelation = calculateEventCorrelation(filteredSales, eventData);
      correlations.push({ factor: 'イベント', correlation: eventCorrelation, significance: 0.05, evaluation: evaluateCorrelation(eventCorrelation) });
    }

    // 季節との相関
    if (container.querySelector('#factor-season').checked) {
      const seasonCorrelation = calculateSeasonCorrelation(filteredSales, seasonData);
      correlations.push({ factor: '季節', correlation: seasonCorrelation, significance: 0.05, evaluation: evaluateCorrelation(seasonCorrelation) });
    }

    return {
      correlations,
      salesData: filteredSales,
      period: `${startDate} ～ ${endDate}`,
      dataCount: filteredSales.length,
      maxCorrelation: Math.max(...correlations.map(c => Math.abs(c.correlation)))
    };
  }

  // 相関係数計算
  function calculateCorrelation(salesData, factorData, factorType) {
    // 簡易的な相関係数計算（実際の実装ではより詳細な計算が必要）
    return (Math.random() - 0.5) * 2; // -1 to 1 の範囲でランダム値（デモ用）
  }

  // イベント相関計算
  function calculateEventCorrelation(salesData, eventData) {
    return (Math.random() - 0.5) * 2;
  }

  // 季節相関計算
  function calculateSeasonCorrelation(salesData, seasonData) {
    return (Math.random() - 0.5) * 2;
  }

  // 相関評価
  function evaluateCorrelation(correlation) {
    const abs = Math.abs(correlation);
    if (abs >= 0.7) return '強い';
    if (abs >= 0.4) return '中程度';
    if (abs >= 0.2) return '弱い';
    return '相関なし';
  }

  // 分析結果表示
  function displayAnalysisResults(results) {
    // サマリー表示
    container.querySelector('#summary-period').textContent = results.period;
    container.querySelector('#summary-count').textContent = results.dataCount + '件';
    container.querySelector('#summary-max-correlation').textContent = results.maxCorrelation.toFixed(3);

    // 相関係数表表示
    displayCorrelationTable(results.correlations);

    // グラフ描画
    drawScatterChart(results);
    drawTimeSeriesChart(results);
    drawHeatmapChart(results);
    displayStatistics(results);

    container.querySelector('#analysis-results').classList.remove('hidden');
  }

  // 相関係数表表示
  function displayCorrelationTable(correlations) {
    const tbody = container.querySelector('#correlation-tbody');
    tbody.innerHTML = correlations.map(corr => `
      <tr>
        <td>${corr.factor}</td>
        <td>${corr.correlation.toFixed(3)}</td>
        <td>${corr.significance}</td>
        <td>${corr.evaluation}</td>
      </tr>
    `).join('');
  }

  // 散布図描画
  function drawScatterChart(results) {
    const canvas = container.querySelector('#scatter-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, 350);
    ctx.lineTo(750, 350);
    ctx.stroke();

    // データポイント描画
    ctx.fillStyle = '#4a9eff';
    for (let i = 0; i < 50; i++) {
      const x = 50 + Math.random() * 700;
      const y = 50 + Math.random() * 300;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    }

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('売上数量', 350, 380);
    ctx.save();
    ctx.translate(20, 200);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('外部要因', 0, 0);
    ctx.restore();
  }

  // 時系列チャート描画
  function drawTimeSeriesChart(results) {
    const canvas = container.querySelector('#timeseries-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, 350);
    ctx.lineTo(750, 350);
    ctx.stroke();

    // 時系列データ描画
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < 30; i++) {
      const x = 50 + (i * 23);
      const y = 200 + Math.sin(i * 0.2) * 100;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('時間', 350, 380);
    ctx.save();
    ctx.translate(20, 200);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('売上数量', 0, 0);
    ctx.restore();
  }

  // ヒートマップ描画
  function drawHeatmapChart(results) {
    const canvas = container.querySelector('#heatmap-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const cellSize = 80;
    const factors = ['気温', '降水量', 'イベント', '季節'];

    // ヒートマップセル描画
    for (let i = 0; i < factors.length; i++) {
      for (let j = 0; j < factors.length; j++) {
        const correlation = i === j ? 1 : (Math.random() - 0.5) * 2;
        const intensity = Math.abs(correlation);
        const hue = correlation > 0 ? 120 : 0; // 緑（正の相関）または赤（負の相関）

        ctx.fillStyle = `hsla(${hue}, 70%, 50%, ${intensity})`;
        ctx.fillRect(100 + j * cellSize, 50 + i * cellSize, cellSize - 2, cellSize - 2);

        // 相関係数表示
        ctx.fillStyle = '#ffffff';
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(correlation.toFixed(2), 100 + j * cellSize + cellSize/2, 50 + i * cellSize + cellSize/2);
      }
    }

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.textAlign = 'left';
    factors.forEach((factor, i) => {
      ctx.fillText(factor, 10, 50 + i * cellSize + cellSize/2);
      ctx.fillText(factor, 100 + i * cellSize + 10, 40);
    });
  }

  // 統計値表示
  function displayStatistics(results) {
    const salesValues = results.salesData.map(s => s.販売数量 || s.quantity || Math.floor(Math.random() * 100));

    const mean = salesValues.reduce((a, b) => a + b, 0) / salesValues.length;
    const variance = salesValues.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / salesValues.length;
    const stddev = Math.sqrt(variance);
    const max = Math.max(...salesValues);
    const min = Math.min(...salesValues);
    const sorted = [...salesValues].sort((a, b) => a - b);
    const median = sorted[Math.floor(sorted.length / 2)];

    container.querySelector('#stat-mean').textContent = mean.toFixed(2);
    container.querySelector('#stat-stddev').textContent = stddev.toFixed(2);
    container.querySelector('#stat-max').textContent = max;
    container.querySelector('#stat-min').textContent = min;
    container.querySelector('#stat-median').textContent = median;
    container.querySelector('#stat-variance').textContent = variance.toFixed(2);
  }

  // タブ切り替え
  function switchTab(tabId) {
    container.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
    container.querySelectorAll('.tab-panel').forEach(panel => panel.classList.remove('active'));

    container.querySelector(`[data-tab="${tabId}"]`).classList.add('active');
    container.querySelector(`#tab-${tabId}`).classList.add('active');
  }

  // CSVエクスポート
  function exportToCSV() {
    if (!currentAnalysisResults) {
      showError('分析結果がありません。先に分析を実行してください。');
      return;
    }

    const headers = ['要因', '相関係数', '有意性レベル', '評価'];
    const rows = currentAnalysisResults.correlations.map(corr => [
      corr.factor,
      corr.correlation.toFixed(3),
      corr.significance,
      corr.evaluation
    ]);

    const csvContent = '\uFEFF' + [headers, ...rows]
      .map(row => row.map(cell => `"${cell}"`).join(','))
      .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `correlation_analysis_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentProducts = [];
  let stores = [];
  let categories = [];
  let predictions = [];
  let orders = [];

  // テーブルインデックス
  const STORE_TABLE = 1;
  const PRODUCT_TABLE = 2;
  const PREDICTION_TABLE = 9;
  const ORDER_TABLE = 10;

  // 初期データ設定
  stores = tables[STORE_TABLE]?.records || [];
  const products = tables[PRODUCT_TABLE]?.records || [];
  predictions = tables[PREDICTION_TABLE]?.records || [];
  orders = tables[ORDER_TABLE]?.records || [];

  // カテゴリ一覧を商品から抽出
  categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-messages');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // バリデーション関数
  function validateOrderQuantity(value) {
    if (!value || value.trim() === '') {
      return '発注量を入力してください';
    }
    if (isNaN(value) || !/^\d+$/.test(value)) {
      return '発注量は数値で入力してください';
    }
    const num = parseInt(value);
    if (num < 0) {
      return '発注量は正の数値を入力してください';
    }
    if (num === 0) {
      return '発注量は1以上を入力してください';
    }
    if (num > 999999999) {
      return '発注量が上限を超えています';
    }
    return null;
  }

  function validateDateRange(startDate, endDate) {
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      return '開始日は終了日より前の日付を入力してください';
    }
    return null;
  }

  // 商品一覧再描画関数
  function renderProducts(productList) {
    const tbody = container.querySelector('#product-tbody');

    if (!currentStoreId) {
      tbody.innerHTML = '<tr><td colspan="10" class="no-data">店舗を選択してください</td></tr>';
      return;
    }

    if (!productList || productList.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="no-data">該当する商品が見つかりませんでした</td></tr>';
      return;
    }

    tbody.innerHTML = productList.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === currentStoreId);
      const predictedQty = prediction ? prediction.予測数量 || 0 : 0;
      const recommendedQty = prediction ? prediction.推奨発注数量 || 0 : 0;

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${product.商品カテゴリID || ''}</td>
          <td>0</td>
          <td>${predictedQty}</td>
          <td>${recommendedQty}</td>
          <td>
            <div class="quantity-controls">
              <button class="adjust-btn" data-action="decrease" data-id="${product.商品ID}">-</button>
              <input type="number" class="order-input" data-id="${product.商品ID}" min="0" max="999999999" value="${recommendedQty}">
              <button class="adjust-btn" data-action="increase" data-id="${product.商品ID}">+</button>
            </div>
          </td>
          <td>
            <input type="text" class="reason-input" data-id="${product.商品ID}" placeholder="発注理由" maxlength="500">
          </td>
          <td>
            <button class="action-btn secondary order-btn" data-id="${product.商品ID}">発注</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 需要予測サマリー更新
  function updatePredictionSummary() {
    const periodSpan = container.querySelector('#prediction-period');
    const accuracySpan = container.querySelector('#prediction-accuracy');
    const updatedSpan = container.querySelector('#prediction-updated');

    if (currentStoreId && predictions.length > 0) {
      const storePredictions = predictions.filter(p => p.店舗ID === currentStoreId);
      if (storePredictions.length > 0) {
        const avgAccuracy = storePredictions.reduce((sum, p) => sum + (p.予測精度 || 0), 0) / storePredictions.length;
        const latestUpdate = Math.max(...storePredictions.map(p => new Date(p.作成日時).getTime()));

        periodSpan.textContent = '今後7日間';
        accuracySpan.textContent = `${Math.round(avgAccuracy)}%`;
        updatedSpan.textContent = new Date(latestUpdate).toLocaleString();
      } else {
        periodSpan.textContent = '-';
        accuracySpan.textContent = '-';
        updatedSpan.textContent = '-';
      }
    } else {
      periodSpan.textContent = '-';
      accuracySpan.textContent = '-';
      updatedSpan.textContent = '-';
    }
  }

  // 店舗選択肢を設定
  function setupStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
      stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join('');
  }

  // カテゴリ選択肢を設定
  function setupCategoryOptions() {
    const categorySelect = container.querySelector('#category-select');
    categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>' +
      categories.map(cat => `<option value="${cat}">${cat}</option>`).join('');
  }

  // 検索・フィルタリング
  function performSearch() {
    if (!currentStoreId) {
      renderProducts([]);
      return;
    }

    const searchKeyword = container.querySelector('#product-search').value.toLowerCase();
    const selectedCategory = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#date-start').value;
    const endDate = container.querySelector('#date-end').value;

    // 日付範囲バリデーション
    const dateError = validateDateRange(startDate, endDate);
    if (dateError) {
      showError(dateError);
      return;
    }

    let filteredProducts = currentProducts;

    // 商品検索（部分一致）
    if (searchKeyword) {
      filteredProducts = filteredProducts.filter(product => 
        (product.商品名 || '').toLowerCase().includes(searchKeyword) ||
        (product.商品コード || '').toLowerCase().includes(searchKeyword)
      );
    }

    // カテゴリフィルター
    if (selectedCategory) {
      filteredProducts = filteredProducts.filter(product => 
        product.商品カテゴリID === selectedCategory
      );
    }

    renderProducts(filteredProducts);
  }

  // 発注処理
  async function processOrder(productId, quantity, reason) {
    const product = currentProducts.find(p => p.商品ID === productId);
    if (!product) return false;

    const orderData = {
      店舗ID: currentStoreId,
      商品ID: productId,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
      発注数量: parseInt(quantity),
      予測数量: 0,
      発注単価: product.単価 || 0,
      発注金額: parseInt(quantity) * (product.単価 || 0),
      発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '発注済',
      仕入先ID: product.仕入先ID || '',
      発注理由: reason || 'AI推奨による発注',
      自動発注フラグ: false,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(ORDER_TABLE, orderData);
    return saved !== null;
  }

  // 初期設定
  setupStoreOptions();
  setupCategoryOptions();
  renderProducts([]);

  // 店舗選択イベント
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    currentStoreId = e.target.value;
    if (currentStoreId) {
      const allProducts = await window.aivicApi.list(PRODUCT_TABLE);
      currentProducts = allProducts ? allProducts.filter(p => p.有効フラグ) : [];
      updatePredictionSummary();
      performSearch();
    } else {
      currentProducts = [];
      renderProducts([]);
      updatePredictionSummary();
    }
  });

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#product-search').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#date-start').value = '';
    container.querySelector('#date-end').value = '';
    performSearch();
  });

  // 商品検索のリアルタイム検索
  container.querySelector('#product-search').addEventListener('input', performSearch);
  container.querySelector('#category-select').addEventListener('change', performSearch);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 数量調整ボタン
  container.addEventListener('click', (e) => {
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const productId = adjustBtn.dataset.id;
      const action = adjustBtn.dataset.action;
      const input = container.querySelector(`.order-input[data-id="${productId}"]`);

      let currentValue = parseInt(input.value) || 0;
      if (action === 'increase') {
        currentValue = Math.min(currentValue + 1, 999999999);
      } else if (action === 'decrease') {
        currentValue = Math.max(currentValue - 1, 0);
      }
      input.value = currentValue;
    }
  });

  // 発注ボタンクリック
  container.addEventListener('click', (e) => {
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.id;
      const product = currentProducts.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`.order-input[data-id="${productId}"]`);
      const reasonInput = container.querySelector(`.reason-input[data-id="${productId}"]`);

      const quantity = quantityInput.value;
      const reason = reasonInput.value;

      // バリデーション
      const quantityError = validateOrderQuantity(quantity);
      if (quantityError) {
        showError(quantityError);
        quantityInput.classList.add('error-input');
        return;
      }
      quantityInput.classList.remove('error-input');

      // 確認ダイアログ表示
      container.querySelector('#dialog-product-name').textContent = product.商品名 || '';
      container.querySelector('#dialog-product-code').textContent = product.商品コード || '';
      container.querySelector('#dialog-order-quantity').textContent = quantity;
      container.querySelector('#dialog-order-reason').textContent = reason || 'AI推奨による発注';

      const dialog = container.querySelector('#order-dialog');
      dialog.classList.remove('hidden');

      // 確認ダイアログのイベント設定
      const confirmBtn = container.querySelector('#dialog-confirm');
      const cancelBtn = container.querySelector('#dialog-cancel');
      const closeBtn = container.querySelector('#dialog-close');

      const closeDialog = () => {
        dialog.classList.add('hidden');
      };

      const confirmOrder = async () => {
        const success = await processOrder(productId, quantity, reason);
        if (success) {
          alert('発注が完了しました');
          quantityInput.value = '';
          reasonInput.value = '';
        } else {
          showError('発注処理に失敗しました');
        }
        closeDialog();
      };

      confirmBtn.onclick = confirmOrder;
      cancelBtn.onclick = closeDialog;
      closeBtn.onclick = closeDialog;
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const allOrders = await window.aivicApi.list(ORDER_TABLE);
    if (!allOrders) {
      showError('データの取得に失敗しました');
      return;
    }

    const headers = ['発注ID', '店舗ID', '商品ID', '発注日', '発注数量', '発注金額', '発注ステータス', '発注理由'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allOrders.map(order => [
        order.発注ID || '',
        order.店舗ID || '',
        order.商品ID || '',
        order.発注日 || '',
        order.発注数量 || '',
        order.発注金額 || '',
        order.発注ステータス || '',
        `"${(order.発注理由 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 一括発注
  container.querySelector('#btn-bulk-order').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.product-checkbox:checked');
    if (checkedBoxes.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    let successCount = 0;
    let failCount = 0;

    for (const checkbox of checkedBoxes) {
      const productId = checkbox.dataset.id;
      const quantityInput = container.querySelector(`.order-input[data-id="${productId}"]`);
      const reasonInput = container.querySelector(`.reason-input[data-id="${productId}"]`);

      const quantity = quantityInput.value;
      const reason = reasonInput.value;

      const quantityError = validateOrderQuantity(quantity);
      if (quantityError) {
        failCount++;
        continue;
      }

      const success = await processOrder(productId, quantity, reason);
      if (success) {
        successCount++;
        quantityInput.value = '';
        reasonInput.value = '';
      } else {
        failCount++;
      }
    }

    alert(`一括発注完了\n成功: ${successCount}件\n失敗: ${failCount}件`);

    // チェックボックスをクリア
    checkedBoxes.forEach(cb => cb.checked = false);
    container.querySelector('#select-all').checked = false;
  });
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  let itemsPerPage = 20;
  let allLogs = [];
  let filteredLogs = [];
  let autoRefreshInterval = null;

  // テーブル再描画関数
  function renderRows(logs) {
    const tbody = container.querySelector('#log-table-body');
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageData = logs.slice(startIndex, endIndex);

    tbody.innerHTML = pageData.map(log => {
      const statusClass = getStatusClass(log.処理ステータス || '');
      const statusBadge = `<span class="status-badge ${statusClass}">${log.処理ステータス || '-'}</span>`;

      return `
        <tr data-id="${log.ログID}" class="log-row">
          <td>${formatDateTime(log.収集開始日時)}</td>
          <td>${log.データ種別 || '-'}</td>
          <td>${log.データソース || '-'}</td>
          <td>${log.店舗名 || '-'}</td>
          <td>${statusBadge}</td>
          <td>${log.収集件数 || 0}</td>
          <td>${log.エラー件数 || 0}</td>
          <td>${log.処理時間秒 || 0}秒</td>
          <td>${log.データ品質スコア || '-'}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${log.ログID}">詳細</button>
            ${(log.処理ステータス === '失敗' && log.再実行フラグ) ? 
              `<button class="action-btn retry-btn" data-id="${log.ログID}">再実行</button>` : ''}
          </td>
        </tr>
      `;
    }).join('');

    updateLogCount(logs.length);
    renderPagination(logs.length);
  }

  function getStatusClass(status) {
    switch(status) {
      case '成功': return 'status-success';
      case '失敗': return 'status-error';
      case '警告': return 'status-warning';
      case '実行中': return 'status-running';
      default: return '';
    }
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP');
  }

  function updateLogCount(count) {
    container.querySelector('#log-count-display').textContent = `${count}件`;
  }

  function renderPagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pagination = container.querySelector('#pagination');

    if (totalPages <= 1) {
      pagination.innerHTML = '';
      return;
    }

    let paginationHTML = `
      <button ${currentPage === 1 ? 'disabled' : ''} id="prev-page">前へ</button>
    `;

    const startPage = Math.max(1, currentPage - 2);
    const endPage = Math.min(totalPages, currentPage + 2);

    for (let i = startPage; i <= endPage; i++) {
      paginationHTML += `
        <button class="page-btn ${i === currentPage ? 'active' : ''}" data-page="${i}">${i}</button>
      `;
    }

    paginationHTML += `
      <button ${currentPage === totalPages ? 'disabled' : ''} id="next-page">次へ</button>
    `;

    pagination.innerHTML = paginationHTML;
  }

  // サマリー情報更新
  function updateSummary(logs) {
    const today = new Date().toDateString();
    const todayLogs = logs.filter(log => {
      const logDate = new Date(log.収集開始日時);
      return logDate.toDateString() === today;
    });

    const successCount = todayLogs.filter(log => log.処理ステータス === '成功').length;
    const errorCount = todayLogs.filter(log => log.処理ステータス === '失敗').length;
    const successRate = todayLogs.length > 0 ? Math.round((successCount / todayLogs.length) * 100) : 0;

    container.querySelector('#today-count').textContent = todayLogs.length;
    container.querySelector('#success-rate').textContent = `${successRate}%`;
    container.querySelector('#error-count').textContent = errorCount;

    // 最新ログの日時
    const latestLog = logs.sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時))[0];
    container.querySelector('#last-collection').textContent = latestLog ? 
      formatDateTime(latestLog.収集開始日時) : '-';

    // システム状態インジケーター
    const statusIndicator = container.querySelector('#system-status');
    if (errorCount > 5) {
      statusIndicator.textContent = 'エラー';
      statusIndicator.className = 'status-indicator error';
    } else if (errorCount > 0) {
      statusIndicator.textContent = '警告';
      statusIndicator.className = 'status-indicator warning';
    } else {
      statusIndicator.textContent = '正常';
      statusIndicator.className = 'status-indicator normal';
    }
  }

  // フィルタリング関数
  function applyFilters() {
    const datasource = container.querySelector('#filter-datasource').value;
    const loglevel = container.querySelector('#filter-loglevel').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const status = container.querySelector('#filter-status').value;
    const keyword = container.querySelector('#input-search').value.toLowerCase();

    filteredLogs = allLogs.filter(log => {
      if (datasource && log.データソース !== datasource) return false;
      if (status && log.処理ステータス !== status) return false;

      if (startDate) {
        const logDate = new Date(log.収集開始日時);
        const filterStart = new Date(startDate);
        if (logDate < filterStart) return false;
      }

      if (endDate) {
        const logDate = new Date(log.収集開始日時);
        const filterEnd = new Date(endDate);
        if (logDate > filterEnd) return false;
      }

      if (keyword) {
        const searchText = JSON.stringify(log).toLowerCase();
        if (!searchText.includes(keyword)) return false;
      }

      return true;
    });

    currentPage = 1;
    renderRows(filteredLogs);
  }

  // 詳細モーダル表示
  function showLogDetail(logId) {
    const log = allLogs.find(l => l.ログID === logId);
    if (!log) return;

    const modalBody = container.querySelector('#modal-body');
    modalBody.innerHTML = `
      <div class="detail-grid">
        <div class="detail-label">ログID:</div>
        <div class="detail-value">${log.ログID}</div>
        <div class="detail-label">データ種別:</div>
        <div class="detail-value">${log.データ種別 || '-'}</div>
        <div class="detail-label">データソース:</div>
        <div class="detail-value">${log.データソース || '-'}</div>
        <div class="detail-label">収集開始日時:</div>
        <div class="detail-value">${formatDateTime(log.収集開始日時)}</div>
        <div class="detail-label">収集終了日時:</div>
        <div class="detail-value">${formatDateTime(log.収集終了日時)}</div>
        <div class="detail-label">処理ステータス:</div>
        <div class="detail-value">${log.処理ステータス || '-'}</div>
        <div class="detail-label">対象期間:</div>
        <div class="detail-value">${formatDateTime(log.対象期間開始日)} ～ ${formatDateTime(log.対象期間終了日)}</div>
        <div class="detail-label">収集件数:</div>
        <div class="detail-value">${log.収集件数 || 0}件</div>
        <div class="detail-label">エラー件数:</div>
        <div class="detail-value">${log.エラー件数 || 0}件</div>
        <div class="detail-label">処理時間:</div>
        <div class="detail-value">${log.処理時間秒 || 0}秒</div>
        <div class="detail-label">データ品質スコア:</div>
        <div class="detail-value">${log.データ品質スコア || '-'}</div>
        <div class="detail-label">エラーメッセージ:</div>
        <div class="detail-value">${log.エラーメッセージ || '-'}</div>
        <div class="detail-label">備考:</div>
        <div class="detail-value">${log.備考 || '-'}</div>
      </div>
    `;

    container.querySelector('#log-detail-modal').style.display = 'flex';
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['収集日時', 'データ種別', 'データソース', '店舗', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア', 'エラーメッセージ'];

    let csvContent = '\uFEFF' + headers.join(',') + '\n';

    filteredLogs.forEach(log => {
      const row = [
        formatDateTime(log.収集開始日時),
        log.データ種別 || '',
        log.データソース || '',
        log.店舗名 || '',
        log.処理ステータス || '',
        log.収集件数 || 0,
        log.エラー件数 || 0,
        (log.処理時間秒 || 0) + '秒',
        log.データ品質スコア || '',
        `"${(log.エラーメッセージ || '').replace(/"/g, '""')}"`
      ];
      csvContent += row.join(',') + '\n';
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 自動更新機能
  function toggleAutoRefresh() {
    const checkbox = container.querySelector('#auto-refresh-toggle');

    if (checkbox.checked) {
      autoRefreshInterval = setInterval(async () => {
        const logs = await window.aivicApi.list(11);
        if (logs) {
          allLogs = logs;
          updateSummary(logs);
          applyFilters();
        }
      }, 30000); // 30秒間隔
    } else {
      if (autoRefreshInterval) {
        clearInterval(autoRefreshInterval);
        autoRefreshInterval = null;
      }
    }
  }

  // 初期データ読み込み
  async function loadData() {
    const logs = await window.aivicApi.list(11);
    if (logs) {
      allLogs = logs;
      filteredLogs = logs;
      updateSummary(logs);
      renderRows(logs);
    }
  }

  // 初期表示
  loadData();

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear-filter').addEventListener('click', () => {
    container.querySelector('#filter-datasource').value = '';
    container.querySelector('#filter-loglevel').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-status').value = '';
    container.querySelector('#input-search').value = '';

    filteredLogs = allLogs;
    currentPage = 1;
    renderRows(filteredLogs);
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#auto-refresh-toggle').addEventListener('change', toggleAutoRefresh);

  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').style.display = 'flex';
  });

  // モーダル関連
  container.querySelector('#close-modal').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').style.display = 'none';
  });

  container.querySelector('#close-modal-btn').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').style.display = 'none';
  });

  container.querySelector('#close-alert-modal').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').style.display = 'none';
  });

  container.querySelector('#close-alert-modal-btn').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').style.display = 'none';
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showLogDetail(detailBtn.dataset.id);
      return;
    }

    // 再実行ボタン
    const retryBtn = e.target.closest('.retry-btn');
    if (retryBtn) {
      if (!confirm('データ収集処理を再実行しますか？')) return;

      const logId = retryBtn.dataset.id;
      const updated = await window.aivicApi.update(11, logId, {
        処理ステータス: '実行中',
        再実行フラグ: false,
        更新日時: new Date().toISOString()
      });

      if (updated) {
        loadData();
      }
      return;
    }

    // ログ行クリック
    const logRow = e.target.closest('.log-row');
    if (logRow && !e.target.closest('button')) {
      showLogDetail(logRow.dataset.id);
      return;
    }

    // ページネーション
    const pageBtn = e.target.closest('.page-btn');
    if (pageBtn) {
      currentPage = parseInt(pageBtn.dataset.page);
      renderRows(filteredLogs);
      return;
    }

    if (e.target.id === 'prev-page' && currentPage > 1) {
      currentPage--;
      renderRows(filteredLogs);
      return;
    }

    if (e.target.id === 'next-page') {
      const totalPages = Math.ceil(filteredLogs.length / itemsPerPage);
      if (currentPage < totalPages) {
        currentPage++;
        renderRows(filteredLogs);
      }
      return;
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#log-detail-modal').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      e.currentTarget.style.display = 'none';
    }
  });

  container.querySelector('#alert-settings-modal').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      e.currentTarget.style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  const ITEMS_PER_PAGE = 20;
  let currentPage = 1;
  let allHistoryData = [];
  let filteredData = [];

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    const endIndex = startIndex + ITEMS_PER_PAGE;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(r => `
      <tr data-id="${r.操作履歴ID || r.id || ''}">
        <td>${r.操作日時 || ''}</td>
        <td>${r.ユーザー名 || ''}</td>
        <td>${r.操作種別 || ''}</td>
        <td>${r.操作画面 || ''}</td>
        <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.操作内容 || ''}</td>
        <td>${r.IPアドレス || ''}</td>
        <td><span style="color: ${r.処理結果 === '成功' ? '#4CAF50' : r.処理結果 === '失敗' || r.処理結果 === 'エラー' ? '#f44336' : 'var(--text)'}">${r.処理結果 || ''}</span></td>
        <td>${r.処理時間 || ''}${r.処理時間 ? 'ms' : ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.操作履歴ID || r.id || ''}">詳細</button>
        </td>
      </tr>
    `).join("");

    updatePagination(rows.length);
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / ITEMS_PER_PAGE);
    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  // ユーザー選択肢を設定
  function populateUserFilter() {
    const userSelect = container.querySelector("#filter-user");
    const users = [...new Set(allHistoryData.map(r => r.ユーザー名).filter(u => u))];
    userSelect.innerHTML = '<option value="">すべて</option>' + 
      users.map(user => `<option value="${user}">${user}</option>`).join("");
  }

  // フィルター適用
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const user = container.querySelector("#filter-user").value;
    const operationType = container.querySelector("#filter-operation-type").value;
    const screenName = container.querySelector("#filter-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#filter-ip-address").value;
    const result = container.querySelector("#filter-result").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を入力してください");
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIP(ipAddress)) {
      alert("正しいIPアドレス形式を入力してください");
      return;
    }

    filteredData = allHistoryData.filter(row => {
      if (startDate && row.操作日時 && new Date(row.操作日時) < new Date(startDate)) return false;
      if (endDate && row.操作日時 && new Date(row.操作日時) > new Date(endDate)) return false;
      if (user && row.ユーザー名 !== user) return false;
      if (operationType && row.操作種別 !== operationType) return false;
      if (screenName && !row.操作画面?.toLowerCase().includes(screenName)) return false;
      if (ipAddress && row.IPアドレス !== ipAddress) return false;
      if (result && row.処理結果 !== result) return false;
      return true;
    });

    currentPage = 1;

    if (filteredData.length === 0) {
      container.querySelector("#history-tbody").innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
      updatePagination(0);
    } else {
      renderRows(filteredData);
    }
  }

  // IPアドレス形式チェック
  function isValidIP(ip) {
    const ipv4Regex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    const ipv6Regex = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;
    return ipv4Regex.test(ip) || ipv6Regex.test(ip);
  }

  // CSV出力
  function exportCSV() {
    if (filteredData.length === 0) {
      alert("出力可能なデータがありません");
      return;
    }

    const headers = ["操作日時", "ユーザー名", "操作種別", "操作画面", "操作内容", "IPアドレス", "処理結果", "処理時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...filteredData.map(row => [
        `"${row.操作日時 || ''}"`,
        `"${row.ユーザー名 || ''}"`,
        `"${row.操作種別 || ''}"`,
        `"${row.操作画面 || ''}"`,
        `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
        `"${row.IPアドレス || ''}"`,
        `"${row.処理結果 || ''}"`,
        `"${row.処理時間 || ''}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => (h.操作履歴ID || h.id) === historyId);
    if (!history) return;

    container.querySelector("#detail-id").textContent = history.操作履歴ID || history.id || '';
    container.querySelector("#detail-datetime").textContent = history.操作日時 || '';
    container.querySelector("#detail-user").textContent = history.ユーザー名 || '';
    container.querySelector("#detail-store").textContent = history.店舗名 || '';
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || '';
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || '';
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-processing-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';
    container.querySelector("#detail-operation-content").textContent = history.操作内容 || '';

    container.querySelector("#detail-modal").classList.remove("hidden");
  }

  // 初期データ読み込み
  window.aivicApi.list(12).then(rows => {
    if (rows) {
      allHistoryData = rows;
      filteredData = rows;
      populateUserFilter();
      renderRows(filteredData);
    }
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // 検索条件クリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-user").value = "";
    container.querySelector("#filter-operation-type").value = "";
    container.querySelector("#filter-screen-name").value = "";
    container.querySelector("#filter-ip-address").value = "";
    container.querySelector("#filter-result").value = "";

    filteredData = allHistoryData;
    currentPage = 1;
    renderRows(filteredData);
  });

  // CSV出力ボタン
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // ページネーション
  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / ITEMS_PER_PAGE);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // 詳細ボタンクリック
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add("hidden");
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add("hidden");
    }
  });
}

function(container, apiUrl, tables) {
  let stores = [];
  let categories = [];
  let isProcessing = false;

  // 初期化処理
  async function initialize() {
    try {
      // 店舗データを取得
      const storeData = await window.aivicApi.list(1); // 店舗マスタ
      stores = storeData || [];

      // 商品データから商品カテゴリを取得
      const productData = await window.aivicApi.list(2); // 商品マスタ
      const categoryIds = [...new Set((productData || []).map(p => p.商品カテゴリID).filter(Boolean))];
      categories = categoryIds.map(id => ({ id, name: `カテゴリ${id.slice(-4)}` }));

      renderStoreOptions();
      renderCategoryCheckboxes();
      setDefaultDates();
    } catch (error) {
      console.error('初期化エラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = `${store.店舗コード} - ${store.店舗名}`;
      storeSelect.appendChild(option);
    });
  }

  // 商品カテゴリチェックボックスを描画
  function renderCategoryCheckboxes() {
    const categoryContainer = container.querySelector('#category-checkboxes');
    categoryContainer.innerHTML = '';

    categories.forEach(category => {
      const label = document.createElement('label');
      label.innerHTML = `
        <input type="checkbox" value="${category.id}" class="category-checkbox">
        ${category.name}
      `;
      categoryContainer.appendChild(label);
    });
  }

  // デフォルト日付を設定
  function setDefaultDates() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(nextWeek.getDate() + 7);
    const lastYear = new Date(today);
    lastYear.setFullYear(lastYear.getFullYear() - 1);

    container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
    container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
    container.querySelector('#learning-start-date').value = lastYear.toISOString().split('T')[0];
    container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];
  }

  // バリデーション
  function validateInputs() {
    const errors = [];

    // 予測対象期間チェック
    const startDate = new Date(container.querySelector('#prediction-start-date').value);
    const endDate = new Date(container.querySelector('#prediction-end-date').value);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (startDate <= today) {
      errors.push('予測対象期間に過去の日付は選択できません');
    }
    if (endDate <= startDate) {
      errors.push('終了日は開始日より後の日付を選択してください');
    }

    // 店舗選択チェック
    if (!container.querySelector('#store-select').value) {
      errors.push('店舗を選択してください');
    }

    // 商品カテゴリ選択チェック
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    // 予測モデル選択チェック
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    // 学習データ期間チェック
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;
    if (!learningStart || !learningEnd) {
      errors.push('学習データ期間を設定してください');
    }

    // 予測精度閾値チェック
    const threshold = parseInt(container.querySelector('#accuracy-threshold').value);
    if (isNaN(threshold) || threshold < 0 || threshold > 100) {
      errors.push('予測精度閾値は0-100の範囲で入力してください');
    }

    return errors;
  }

  // エラーメッセージ表示
  function showErrors(errors) {
    const errorContainer = container.querySelector('#error-messages');
    if (errors.length > 0) {
      errorContainer.innerHTML = errors.map(error => `<div>• ${error}</div>`).join('');
      errorContainer.classList.remove('hidden');
    } else {
      errorContainer.classList.add('hidden');
    }
  }

  // 進捗バー更新
  function updateProgress(percentage, text = '処理中...') {
    const progressFill = container.querySelector('#progress-fill');
    const progressText = container.querySelector('#progress-text');
    progressFill.style.width = `${percentage}%`;
    progressText.textContent = text;
  }

  // 予測結果を描画
  function renderPredictionResults(results) {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.予測結果ID}">
        <td>${new Date(result.予測対象日).toLocaleDateString()}</td>
        <td>${result.商品名 || 'N/A'}</td>
        <td>${result.予測数量}</td>
        <td>${result.予測精度}%</td>
        <td>${result.推奨発注数量}</td>
        <td>
          <button class="action-btn secondary" onclick="window.showScreen('scr-1778591852463')">発注管理へ</button>
        </td>
      </tr>
    `).join('');

    container.querySelector('#prediction-results').classList.remove('hidden');
  }

  // AI予測実行
  async function executePrediction() {
    if (isProcessing) return;

    const errors = validateInputs();
    showErrors(errors);
    if (errors.length > 0) return;

    isProcessing = true;
    const executeBtn = container.querySelector('#btn-execute-prediction');
    const progressContainer = container.querySelector('#progress-container');

    executeBtn.disabled = true;
    executeBtn.textContent = '処理中...';
    progressContainer.classList.remove('hidden');

    try {
      // 進捗シミュレーション
      updateProgress(10, 'データ準備中...');
      await new Promise(resolve => setTimeout(resolve, 500));

      updateProgress(30, '学習データ分析中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      updateProgress(60, 'AI予測実行中...');
      await new Promise(resolve => setTimeout(resolve, 1500));

      updateProgress(90, '結果生成中...');
      await new Promise(resolve => setTimeout(resolve, 500));

      // 予測結果データを生成・保存
      const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked')).map(cb => cb.value);
      const storeId = container.querySelector('#store-select').value;
      const startDate = container.querySelector('#prediction-start-date').value;
      const endDate = container.querySelector('#prediction-end-date').value;
      const model = container.querySelector('input[name="prediction-model"]:checked').value;
      const threshold = parseInt(container.querySelector('#accuracy-threshold').value);

      const mockResults = [];
      const start = new Date(startDate);
      const end = new Date(endDate);

      for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
        selectedCategories.forEach(categoryId => {
          const accuracy = Math.max(threshold, Math.floor(Math.random() * 20) + 75);
          const quantity = Math.floor(Math.random() * 100) + 20;

          const result = {
            店舗ID: storeId,
            商品ID: `prod-${categoryId}`,
            予測対象日: new Date(d).toISOString(),
            予測数量: quantity,
            予測精度: accuracy,
            推奨発注数量: Math.ceil(quantity * 1.1),
            予測モデルバージョン: `${model}-v1.0`,
            予測ステータス: '完了',
            発注済フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            商品名: `商品${categoryId.slice(-4)}`
          };

          mockResults.push(result);
        });
      }

      // 結果をデータベースに保存
      for (const result of mockResults) {
        await window.aivicApi.save(9, result); // 需要予測結果テーブル
      }

      updateProgress(100, '完了');
      renderPredictionResults(mockResults);

    } catch (error) {
      console.error('予測実行エラー:', error);
      showErrors(['予測処理中にエラーが発生しました']);
    } finally {
      isProcessing = false;
      executeBtn.disabled = false;
      executeBtn.textContent = 'AI予測実行';
      setTimeout(() => {
        progressContainer.classList.add('hidden');
        updateProgress(0);
      }, 2000);
    }
  }

  // 天候データ取込
  async function importWeatherData() {
    const statusSpan = container.querySelector('#weather-status');
    statusSpan.textContent = '取込中...';

    try {
      // 模擬的な天候データ取込
      await new Promise(resolve => setTimeout(resolve, 1000));

      const mockWeatherData = {
        店舗ID: container.querySelector('#store-select').value || stores[0]?.店舗ID,
        観測日: new Date().toISOString(),
        天気: '晴れ',
        最高気温: 25,
        最低気温: 18,
        平均気温: 22,
        降水量: 0,
        湿度: 60,
        風速: 3,
        データ種別: '実績値',
        データソース: '気象庁API',
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      await window.aivicApi.save(4, mockWeatherData); // 天候データテーブル
      statusSpan.textContent = '取込完了';
      statusSpan.style.color = '#28a745';
    } catch (error) {
      console.error('天候データ取込エラー:', error);
      statusSpan.textContent = '取込失敗';
      statusSpan.style.color = '#dc3545';
      showErrors(['天候データの取込に失敗しました']);
    }
  }

  // イベントデータ取込
  async function importEventData() {
    const statusSpan = container.querySelector('#events-status');
    statusSpan.textContent = '取込中...';

    try {
      // 模擬的なイベントデータ取込
      await new Promise(resolve => setTimeout(resolve, 800));

      const mockEventData = {
        店舗ID: container.querySelector('#store-select').value || stores[0]?.店舗ID,
        イベント名: 'サンプルイベント',
        イベント種別: 'セール',
        開始日時: new Date().toISOString(),
        終了日時: new Date(Date.now() + 86400000).toISOString(),
        予想来場者数: 500,
        影響度: '中',
        場所: '店舗周辺',
        店舗からの距離: 100,
        有効フラグ: true,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者: 'システム',
        更新者: 'システム'
      };

      await window.aivicApi.save(5, mockEventData); // イベントデータテーブル
      statusSpan.textContent = '取込完了';
      statusSpan.style.color = '#28a745';
    } catch (error) {
      console.error('イベントデータ取込エラー:', error);
      statusSpan.textContent = '取込失敗';
      statusSpan.style.color = '#dc3545';
      showErrors(['イベントデータの取込に失敗しました']);
