  // イベントリスナー設定
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-import-weather').addEventListener('click', importWeatherData);
  container.querySelector('#btn-import-events').addEventListener('click', importEventData);

  // 季節要因スライダー
  const seasonalSlider = container.querySelector('#seasonal-factor');
  const seasonalValue = container.querySelector('#seasonal-value');
