function(container, apiUrl, tables) {
  let currentProducts = [];
  let calculationResults = [];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 店舗データを読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      stores.filter(s => s.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 商品データを読み込み
  async function loadProducts() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      currentProducts = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);

      // カテゴリ一覧を作成
      const categories = [...new Set(currentProducts.map(p => p.商品カテゴリID))];
      const categorySelect = container.querySelector('#category-select');
      categories.forEach(catId => {
        const option = document.createElement('option');
        option.value = catId;
        option.textContent = `カテゴリ${catId}`;
        categorySelect.appendChild(option);
      });
    }
  }

  // 商品絞り込み
  function filterProducts() {
    const categoryId = container.querySelector('#category-select').value;
    const searchText = container.querySelector('#product-search').value.toLowerCase();

    let filtered = currentProducts;

    if (categoryId) {
      filtered = filtered.filter(p => p.商品カテゴリID === categoryId);
    }

    if (searchText) {
      filtered = filtered.filter(p => 
        p.商品名.toLowerCase().includes(searchText) || 
        p.商品コード.toLowerCase().includes(searchText)
      );
    }

    return filtered;
  }

  // 需要予測データを取得・表示
  async function updatePrediction() {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;

    if (!storeId || !startDate || !endDate) {
      showError('店舗と対象期間を選択してください');
      return;
    }

    if (new Date(startDate) > new Date() && new Date(endDate) > new Date()) {
      showError('対象期間に過去または現在の日付を含めてください');
      return;
    }

    const predictions = await window.aivicApi.list(8); // 需要予測結果
    if (predictions) {
      const storePredictions = predictions.filter(p => 
        p.店舗ID === storeId &&
        new Date(p.予測対象日) >= new Date(startDate) &&
        new Date(p.予測対象日) <= new Date(endDate)
      );

      if (storePredictions.length > 0) {
        const totalDemand = storePredictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
        const avgAccuracy = storePredictions.reduce((sum, p) => sum + (p.予測精度 || 0), 0) / storePredictions.length;
        const totalRecommended = storePredictions.reduce((sum, p) => sum + (p.推奨発注数量 || 0), 0);

        container.querySelector('#predicted-demand').textContent = totalDemand.toLocaleString();
        container.querySelector('#prediction-accuracy').textContent = `${Math.round(avgAccuracy)}%`;
        container.querySelector('#recommended-order').textContent = totalRecommended.toLocaleString();

        // 簡易チャート表示
        const chartDiv = container.querySelector('#prediction-chart');
        chartDiv.innerHTML = `
          <div style="display: flex; align-items: end; justify-content: space-around; height: 150px; padding: 20px;">
            ${storePredictions.slice(0, 7).map((p, i) => `
              <div style="display: flex; flex-direction: column; align-items: center;">
                <div style="background: var(--primary); width: 20px; height: ${(p.予測数量 || 0) / Math.max(...storePredictions.map(x => x.予測数量 || 0)) * 100}px; margin-bottom: 5px;"></div>
                <small style="color: var(--text-muted);">${new Date(p.予測対象日).getDate()}日</small>
              </div>
            `).join('')}
          </div>
        `;
      } else {
        container.querySelector('#prediction-chart').innerHTML = '<div style="color: var(--text-muted);">選択期間の予測データがありません</div>';
      }
    }
  }

  // 発注量計算
  async function calculateOrderQuantity() {
    const storeId = container.querySelector('#store-select').value;
    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 1;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;
    const manualAdjustment = parseInt(container.querySelector('#manual-adjustment').value) || 0;

    // バリデーション
    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (currentStock < 0) {
      showError('現在在庫数は0以上の値を入力してください');
      return;
    }

    if (isNaN(safetyStock) || safetyStock < 0) {
      showError('安全在庫は数値を入力してください');
      return;
    }

    if (leadTime < 1 || leadTime > 365) {
      showError('リードタイムは1-365日の範囲で入力してください');
      return;
    }

    if (weatherImpact < 0 || weatherImpact > 200) {
      showError('影響度調整は0-200%の範囲で入力してください');
      return;
    }

    if (seasonalFactor < 0) {
      showError('季節補正係数は0以上の値を入力してください');
      return;
    }

    if (manualAdjustment < 0) {
      showError('手動調整値は0以上の値を入力してください');
      return;
    }

    const filteredProducts = filterProducts();
    const predictions = await window.aivicApi.list(8); // 需要予測結果

    calculationResults = filteredProducts.map(product => {
      const productPredictions = predictions?.filter(p => 
        p.店舗ID === storeId && p.商品ID === product.商品ID
      ) || [];

      const baseDemand = productPredictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
      const adjustedDemand = Math.round(baseDemand * (weatherImpact / 100) * seasonalFactor);
      const aiRecommended = Math.max(0, adjustedDemand + safetyStock - currentStock + (adjustedDemand * leadTime / 30));
      const finalQuantity = manualAdjustment > 0 ? manualAdjustment : aiRecommended;

      return {
        商品ID: product.商品ID,
        商品コード: product.商品コード,
        商品名: product.商品名,
        現在在庫: currentStock,
        予測需要: adjustedDemand,
        安全在庫: safetyStock,
        AI推奨量: aiRecommended,
        手動調整後: manualAdjustment,
        最終発注量: finalQuantity
      };
    });

    renderCalculationResults();
  }

  // 計算結果テーブル描画
  function renderCalculationResults() {
    const tbody = container.querySelector('#calculation-results');
    if (calculationResults.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 2rem;">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = calculationResults.map(result => `
      <tr data-id="${result.商品ID}">
        <td>${result.商品コード}</td>
        <td>${result.商品名}</td>
        <td>${result.現在在庫.toLocaleString()}</td>
        <td>${result.予測需要.toLocaleString()}</td>
        <td>${result.安全在庫.toLocaleString()}</td>
        <td>${result.AI推奨量.toLocaleString()}</td>
        <td>${result.手動調整後.toLocaleString()}</td>
        <td style="font-weight: bold; color: var(--primary);">${result.最終発注量.toLocaleString()}</td>
        <td>
          <button class="action-btn secondary adjust-btn" data-id="${result.商品ID}">調整</button>
        </td>
      </tr>
    `).join('');
  }

  // CSVエクスポート
  function exportCSV() {
    if (calculationResults.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '現在在庫', '予測需要', '安全在庫', 'AI推奨量', '手動調整後', '最終発注量'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...calculationResults.map(row => [
        row.商品コード,
        `"${row.商品名}"`,
        row.現在在庫,
        row.予測需要,
        row.安全在庫,
        row.AI推奨量,
        row.手動調整後,
        row.最終発注量
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー設定
  container.querySelector('#btn-filter').addEventListener('click', () => {
    const filtered = filterProducts();
    console.log(`${filtered.length}件の商品が見つかりました`);
  });

  container.querySelector('#btn-predict-update').addEventListener('click', updatePrediction);
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);
  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  // 在庫数変更時の自動再計算
  container.querySelector('#current-stock').addEventListener('blur', () => {
    if (calculationResults.length > 0) {
      calculateOrderQuantity();
    }
  });

  // 調整ボタンのイベントデリゲーション
  container.addEventListener('click', (e) => {
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const productId = adjustBtn.dataset.id;
      const newQuantity = prompt('発注量を入力してください:');
      if (newQuantity !== null && !isNaN(newQuantity) && parseInt(newQuantity) >= 0) {
        const result = calculationResults.find(r => r.商品ID === productId);
        if (result) {
          result.手動調整後 = parseInt(newQuantity);
          result.最終発注量 = parseInt(newQuantity);
          renderCalculationResults();
        }
      }
    }
  });

  // 初期化
  loadStores();
  loadProducts();

  // デフォルト期間設定（過去7日間）
  const today = new Date();
  const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
  container.querySelector('#period-start').value = weekAgo.toISOString().split('T')[0];
  container.querySelector('#period-end').value = today.toISOString().split('T')[0];
}

