  // 発注総額を更新
  function updateTotalAmount() {
    const total = orderItems.reduce((sum, item) => sum + (item.発注数量 * item.単価), 0);
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // AI予測数量を取得（模擬）
  async function getAIPrediction(productId, storeId) {
    try {
      // 需要予測結果テーブルから該当データを検索
      const predictions = await window.aivicApi.list(9) || []; // 需要予測結果
      const prediction = predictions.find(p => 
        p.商品ID === productId && 
        p.店舗ID === storeId && 
        p.予測ステータス === '完了'
      );

      if (prediction) {
        return {
          quantity: prediction.推奨発注数量 || prediction.予測数量 || 0,
          accuracy: prediction.予測精度 || 85,
          basis: `過去の売上データ、季節性、天候要因を分析した結果です。予測精度: ${prediction.予測精度 || 85}%`
        };
      } else {
        // デフォルト予測値を返す
        return {
          quantity: Math.floor(Math.random() * 50) + 10,
          accuracy: 75,
          basis: '過去3ヶ月の売上平均、曜日別傾向、季節要因を考慮した予測です。'
        };
      }
    } catch (error) {
      return {
        quantity: 20,
        accuracy: 70,
        basis: '基本的な需要予測アルゴリズムによる推定値です。'
      };
    }
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      showError('発注日付を入力してください');
      return false;
    }

    if (!deliveryDate) {
      showError('納期を指定してください');
      return false;
    }

    // 過去日付チェック
    const today = new Date().toISOString().split('T')[0];
    if (orderDate < today) {
      showError('発注日に過去の日付は設定できません');
      return false;
    }

    // 納期チェック
    if (deliveryDate < orderDate) {
      showError('納期は発注日以降の日付を設定してください');
      return false;
    }

    if (orderItems.length === 0) {
      showError('発注する商品を選択してください');
      return false;
    }

    return true;
  }

  // イベントリスナー設定

  // 商品検索
  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const categoryId = container.querySelector('#category-select').value;

    let filteredProducts = products.filter(p => p.有効フラグ);

    if (keyword) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 && p.商品名.toLowerCase().includes(keyword)) ||
        (p.商品コード && p.商品コード.toLowerCase().includes(keyword))
      );
    }

    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    renderProductList(filteredProducts);

    if (filteredProducts.length === 0) {
      container.querySelector('#product-list-tbody').innerHTML = 
        '<tr><td colspan="4" style="text-align: center; color: var(--text-muted);">該当する商品が見つかりませんでした</td></tr>';
    }
  });

  // カテゴリ選択変更
  container.querySelector('#category-select').addEventListener('change', () => {
    container.querySelector('#btn-search').click();
  });

  // 商品選択
  container.addEventListener('click', async (e) => {
    const selectBtn = e.target.closest('.select-product-btn');
    if (selectBtn) {
      const productId = selectBtn.dataset.id;
      selectedProduct = products.find(p => p.商品ID === productId);

      if (selectedProduct) {
        // 商品選択エリアを表示
        const quantityArea = container.querySelector('#quantity-setting-area');
        quantityArea.style.display = 'block';

        container.querySelector('#selected-product-name').textContent = selectedProduct.商品名;

        // AI予測を取得
        const storeId = container.querySelector('#store-select').value;
        if (storeId) {
          const prediction = await getAIPrediction(productId, storeId);
          container.querySelector('#ai-predicted-quantity').textContent = prediction.quantity;
          container.querySelector('#manual-quantity').value = prediction.quantity;

          // 予測根拠を保存
          selectedProduct.predictionBasis = prediction.basis;
        }
      }
    }

    // 発注リストに追加
    const addBtn = e.target.closest('#btn-add-to-order');
    if (addBtn && selectedProduct) {
      const quantity = parseInt(container.querySelector('#manual-quantity').value);

      if (!quantity || quantity < 0) {
        showError('手動調整数量は0以上の値を入力してください');
        return;
      }

      // 既存アイテムをチェック
      const existingIndex = orderItems.findIndex(item => item.商品ID === selectedProduct.商品ID);

      if (existingIndex >= 0) {
        orderItems[existingIndex].発注数量 = quantity;
      } else {
        orderItems.push({
          商品ID: selectedProduct.商品ID,
          商品名: selectedProduct.商品名,
          商品コード: selectedProduct.商品コード,
          発注数量: quantity,
          単価: selectedProduct.単価 || 0
        });
      }

      renderOrderList();

      // フォームをリセット
      container.querySelector('#quantity-setting-area').style.display = 'none';
      container.querySelector('#manual-quantity').value = '';
      selectedProduct = null;
    }

    // 発注リストから削除
    const removeBtn = e.target.closest('.remove-item-btn');
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      orderItems.splice(index, 1);
      renderOrderList();
    }

    // 予測根拠表示
    const basisBtn = e.target.closest('#btn-prediction-basis');
    if (basisBtn && selectedProduct) {
      const modal = container.querySelector('#prediction-basis-modal');
      const content = container.querySelector('#prediction-basis-content');
      content.innerHTML = `
        <div style="margin-bottom: 16px;">
          <h4 style="color: var(--text); margin-bottom: 8px;">商品: ${selectedProduct.商品名}</h4>
          <p style="color: var(--text-muted);">${selectedProduct.predictionBasis || 'AI予測根拠データを取得中...'}</p>
        </div>
        <div style="background: var(--bg-main); padding: 12px; border-radius: 4px;">
          <h5 style="color: var(--text); margin-bottom: 8px;">予測要因</h5>
          <ul style="color: var(--text-muted); margin: 0; padding-left: 20px;">
            <li>過去3ヶ月の売上トレンド</li>
            <li>曜日別売上パターン</li>
            <li>季節性要因</li>
            <li>天候・イベント影響</li>
          </ul>
        </div>
      `;
      modal.classList.remove('hidden');
    }

    // 在庫状況確認
    const stockBtn = e.target.closest('#btn-stock-check');
    if (stockBtn && selectedProduct) {
      const modal = container.querySelector('#stock-check-modal');
      const content = container.querySelector('#stock-info-content');

      // 模擬在庫データ
      const currentStock = Math.floor(Math.random() * 100);
      const status = currentStock > 50 ? '十分' : currentStock > 20 ? '注意' : '不足';
      const statusColor = currentStock > 50 ? '#4CAF50' : currentStock > 20 ? '#FF9800' : '#F44336';

      content.innerHTML = `
        <div style="margin-bottom: 16px;">
          <h4 style="color: var(--text); margin-bottom: 8px;">商品: ${selectedProduct.商品名}</h4>
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
            <div>
              <label style="color: var(--text-muted); font-size: 14px;">現在在庫数量</label>
              <div style="color: var(--text); font-size: 24px; font-weight: bold;">${currentStock}個</div>
            </div>
            <div>
              <label style="color: var(--text-muted); font-size: 14px;">在庫ステータス</label>
              <div style="color: ${statusColor}; font-size: 18px; font-weight: bold;">${status}</div>
            </div>
          </div>
          <div style="margin-top: 12px; color: var(--text-muted); font-size: 14px;">
            最終更新: ${new Date().toLocaleString()}
          </div>
        </div>
      `;
      modal.classList.remove('hidden');
    }

    // 過去実績参照
    const pastBtn = e.target.closest('#btn-past-records');
    if (pastBtn && selectedProduct) {
      const modal = container.querySelector('#past-records-modal');
      modal.classList.remove('hidden');
    }

    // 過去実績データ取得
    const getPastDataBtn = e.target.closest('#btn-get-past-data');
    if (getPastDataBtn && selectedProduct) {
      const period = container.querySelector('#past-period-select').value;
      const content = container.querySelector('#past-records-content');

      // 模擬過去実績データ
      const pastData = [];
      for (let i = 0; i < parseInt(period); i++) {
        const date = new Date();
        date.setMonth(date.getMonth() - i);
        pastData.push({
          month: date.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long' }),
          sales: Math.floor(Math.random() * 200) + 50,
          orders: Math.floor(Math.random() * 150) + 30
        });
      }

      content.innerHTML = `
        <h4 style="color: var(--text); margin-bottom: 16px;">商品: ${selectedProduct.商品名}</h4>
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>期間</th>
                <th>売上数量</th>
                <th>発注数量</th>
              </tr>
            </thead>
            <tbody>
              ${pastData.map(data => `
                <tr>
                  <td>${data.month}</td>
                  <td>${data.sales}個</td>
                  <td>${data.orders}個</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `;
    }

    // モーダル閉じる
    const closeModalBtns = [
      '#btn-close-prediction-modal',
      '#btn-close-stock-modal', 
      '#btn-close-past-modal'
    ];

    closeModalBtns.forEach(selector => {
      const btn = e.target.closest(selector);
      if (btn) {
        const modal = btn.closest('[id$="-modal"]');
        modal.classList.add('hidden');
      }
    });

    // 発注書作成
    const createOrderBtn = e.target.closest('#btn-create-order');
    if (createOrderBtn) {
      if (!validateForm()) return;

      try {
        const storeId = container.querySelector('#store-select').value;
        const orderDate = container.querySelector('#order-date').value;
        const deliveryDate = container.querySelector('#delivery-date').value;

        // 各商品の発注データを保存
        for (const item of orderItems) {
          const orderData = {
            店舗ID: storeId,
            商品ID: item.商品ID,
            発注日: orderDate + 'T00:00:00Z',
            納期予定日: deliveryDate + 'T00:00:00Z',
            発注数量: item.発注数量,
            発注単価: item.単価,
            発注金額: item.発注数量 * item.単価,
            発注方法: '手動発注',
            発注ステータス: '発注済',
            仕入先ID: 'default-supplier',
            発注理由: 'AI需要予測に基づく発注',
            自動発注フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'current-user',
            更新者ID: 'current-user'
          };

          await window.aivicApi.save(10, orderData); // 発注データテーブル
        }

        alert('発注書を正常に作成しました');
        window.showScreen('scr-1778591852463'); // 発注管理画面に遷移

      } catch (error) {
        showError('発注書の作成に失敗しました: ' + error.message);
      }
    }
  });

  // 手動調整数量のバリデーション
  container.querySelector('#manual-quantity').addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    if (value < 0) {
      showError('手動調整数量は0以上の値を入力してください');
      e.target.value = 0;
    }
  });

  // モーダル背景クリックで閉じる
  container.addEventListener('click', (e) => {
    if (e.target.id && e.target.id.endsWith('-modal')) {
      e.target.classList.add('hidden');
    }
  });

  // 初期化実行
  init();
}

function(container, apiUrl, tables) {
  let currentStoreId = '';
  let allOrderData = [];
  let selectedOrderIds = new Set();

  // DOM要素の取得
  const storeSelect = container.querySelector('#store-select');
  const orderDate = container.querySelector('#order-date');
  const selectAllCheckbox = container.querySelector('#select-all');
  const sendButton = container.querySelector('#btn-send-selected');
  const exportButton = container.querySelector('#btn-export-csv');
  const tbody = container.querySelector('#order-tbody');
  const noDataMessage = container.querySelector('#no-data-message');
  const messageArea = container.querySelector('#message-area');

  // 店舗マスタのテーブルインデックスを取得
  const storeTableIndex = tables.findIndex(t => t.tableName === '店舗マスタ');
  const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
  const productTableIndex = tables.findIndex(t => t.tableName === '商品マスタ');
  const demandTableIndex = tables.findIndex(t => t.tableName === '需要予測結果');

  // 店舗選択肢を初期化
  async function initStoreOptions() {
    try {
      const stores = await window.aivicApi.list(storeTableIndex);
      if (stores) {
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの取得に失敗:', error);
    }
  }

  // 発注データを取得・表示
  async function loadOrderData(storeId) {
    if (!storeId) {
      allOrderData = [];
      renderOrderTable([]);
      return;
    }

    try {
      const [orders, products] = await Promise.all([
        window.aivicApi.list(orderTableIndex),
        window.aivicApi.list(productTableIndex)
      ]);

      if (orders && products) {
        // 選択した店舗の発注データをフィルタリング
        const storeOrders = orders.filter(order => 
          order.店舗ID === storeId && 
          (order.発注ステータス === '発注済' || order.発注ステータス === '送信待ち')
        );

        // 商品情報と結合
        allOrderData = storeOrders.map(order => {
          const product = products.find(p => p.商品ID === order.商品ID);
          return {
            ...order,
            商品コード: product?.商品コード || '-',
            商品名: product?.商品名 || '-',
            仕入先名: '仕入先A' // 実際は仕入先マスタから取得
          };
        });

        renderOrderTable(allOrderData);

        // 発注日付を設定（最新の発注日を表示）
        if (allOrderData.length > 0) {
          const latestDate = new Date(Math.max(...allOrderData.map(o => new Date(o.発注日))));
          orderDate.textContent = latestDate.toLocaleDateString('ja-JP');
        } else {
          orderDate.textContent = '-';
        }
      }
    } catch (error) {
      console.error('発注データの取得に失敗:', error);
      showMessage('発注データの取得に失敗しました', 'error');
    }
  }

  // 発注テーブルを描画
  function renderOrderTable(orders) {
    if (!orders || orders.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      container.querySelector('.table-wrap').style.display = 'none';
      sendButton.disabled = true;
      return;
    }

    noDataMessage.classList.add('hidden');
    container.querySelector('.table-wrap').style.display = 'block';

    tbody.innerHTML = orders.map(order => {
      const statusClass = getStatusClass(order.発注ステータス);
      const isChecked = selectedOrderIds.has(order.発注ID);

      return `
        <tr data-id="${order.発注ID}">
          <td>
            <input type="checkbox" class="order-checkbox" data-id="${order.発注ID}" ${isChecked ? 'checked' : ''} />
          </td>
          <td>${order.商品コード}</td>
          <td>${order.商品名}</td>
          <td>${order.予測数量 || '-'}</td>
          <td>${order.発注数量}</td>
          <td>${order.仕入先名}</td>
          <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>
            <span class="status-badge ${statusClass}">${order.発注ステータス}</span>
          </td>
        </tr>
      `;
    }).join('');

    updateSendButtonState();
  }

  // ステータスのCSSクラスを取得
  function getStatusClass(status) {
    switch (status) {
      case '送信済': return 'status-sent';
      case '送信失敗': return 'status-failed';
      default: return 'status-pending';
    }
  }

  // 送信ボタンの状態を更新
  function updateSendButtonState() {
    sendButton.disabled = selectedOrderIds.size === 0;
  }

  // メッセージを表示
  function showMessage(text, type = 'success') {
    messageArea.textContent = text;
    messageArea.className = `message-${type}`;
    messageArea.classList.remove('hidden');

    setTimeout(() => {
      messageArea.classList.add('hidden');
    }, 5000);
  }

  // 選択した発注を送信
  async function sendSelectedOrders() {
    if (selectedOrderIds.size === 0) {
      showMessage('発注対象が選択されていません', 'error');
      return;
    }

    if (!confirm(`${selectedOrderIds.size}件の発注を送信しますか？`)) {
      return;
    }

    try {
      let successCount = 0;
      let failCount = 0;

      for (const orderId of selectedOrderIds) {
        try {
          // 発注ステータスを「送信済」に更新
          await window.aivicApi.update(orderTableIndex, orderId, {
            発注ステータス: '送信済',
            更新日時: new Date().toISOString()
          });
          successCount++;
        } catch (error) {
          console.error(`発注ID ${orderId} の送信に失敗:`, error);
          // 送信失敗の場合はステータスを「送信失敗」に更新
          await window.aivicApi.update(orderTableIndex, orderId, {
            発注ステータス: '送信失敗',
            更新日時: new Date().toISOString()
          });
          failCount++;
        }
      }

      // 結果メッセージを表示
      if (failCount === 0) {
        showMessage(`発注データの送信が完了しました（${successCount}件）`, 'success');
      } else {
        showMessage(`送信完了: ${successCount}件、失敗: ${failCount}件`, 'error');
      }

      // 選択をクリア
      selectedOrderIds.clear();
      selectAllCheckbox.checked = false;

      // データを再読み込み
      await loadOrderData(currentStoreId);

    } catch (error) {
      console.error('発注送信処理でエラー:', error);
      showMessage('通信エラーが発生しました。ネットワーク接続を確認してください。', 'error');
    }
  }

  // CSVエクスポート
  function exportToCSV() {
    if (!allOrderData || allOrderData.length === 0) {
      showMessage('エクスポートするデータがありません', 'error');
      return;
    }

    const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
    const csvContent = [
      headers.join(','),
      ...allOrderData.map(order => [
        order.商品コード,
        `"${order.商品名}"`,
        order.予測数量 || 0,
        order.発注数量,
        `"${order.仕入先名}"`,
        order.発注金額 || 0,
        `"${order.発注ステータス}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナーの設定
  storeSelect.addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    selectedOrderIds.clear();
    selectAllCheckbox.checked = false;
    loadOrderData(currentStoreId);
  });

  selectAllCheckbox.addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.order-checkbox');
    checkboxes.forEach(checkbox => {
      checkbox.checked = e.target.checked;
      if (e.target.checked) {
        selectedOrderIds.add(checkbox.dataset.id);
      } else {
        selectedOrderIds.delete(checkbox.dataset.id);
      }
    });
    updateSendButtonState();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;
      if (e.target.checked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.order-checkbox');
      const checkedCount = container.querySelectorAll('.order-checkbox:checked').length;
      selectAllCheckbox.checked = checkedCount === allCheckboxes.length && allCheckboxes.length > 0;
      selectAllCheckbox.indeterminate = checkedCount > 0 && checkedCount < allCheckboxes.length;

      updateSendButtonState();
    }
  });

  sendButton.addEventListener('click', sendSelectedOrders);
  exportButton.addEventListener('click', exportToCSV);

  // 初期化
  initStoreOptions();
}

function(container, apiUrl, tables) {
  let calculationResults = [];

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.style.background = 'rgba(40, 167, 69, 0.1)';
    errorDiv.style.borderColor = '#28a745';
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
      errorDiv.style.background = 'rgba(220, 53, 69, 0.1)';
      errorDiv.style.borderColor = '#dc3545';
    }, 3000);
  }

  // 計算結果テーブル再描画
  function renderResults(results) {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id || ''}">
        <td>${r.productName || ''}</td>
        <td>${r.productCode || ''}</td>
        <td>${r.currentStock || 0}</td>
        <td>${r.forecastDemand || 0}</td>
        <td>${r.safetyStock || 0}</td>
        <td>${r.reorderPoint || 0}</td>
        <td style="font-weight: bold; color: var(--primary);">${r.recommendedOrder || 0}</td>
        <td>${r.leadTime || 0}日</td>
        <td>${r.calculatedAt || ''}</td>
        <td>
          <button class="action-btn secondary order-btn" data-id="${r.id || ''}">発注</button>
        </td>
      </tr>
    `).join('');
  }

  // 店舗選択肢の初期化
  async function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const storeCheckboxes = container.querySelector('#store-checkboxes');

    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        // 単一選択用ドロップダウン
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.filter(s => s.有効フラグ).map(s => 
            `<option value="${s.店舗ID}">${s.店舗名}</option>`
          ).join('');

        // 複数選択用チェックボックス
        storeCheckboxes.innerHTML = stores.filter(s => s.有効フラグ).map(s => `
          <label style="display: flex; align-items: center; gap: 8px;">
            <input type="checkbox" class="store-checkbox" value="${s.店舗ID}">
            <span>${s.店舗名}</span>
          </label>
        `).join('');
      }
    } catch (error) {
      console.error('店舗データの取得に失敗:', error);
    }
  }

  // 発注量計算ロジック
  function calculateOrderQuantity(currentStock, forecastDemand, safetyStock, leadTime, orderCycle) {
    // 発注量 = (予測需要量 × (リードタイム + 発注サイクル) / 発注サイクル) + 安全在庫 - 現在在庫
    const demandDuringLeadTime = forecastDemand * (leadTime + orderCycle) / orderCycle;
    const recommendedOrder = Math.max(0, demandDuringLeadTime + safetyStock - currentStock);
    return Math.ceil(recommendedOrder);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }
    if (!category) {
      showError('商品カテゴリを選択してください');
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError('計算対象期間を設定してください');
      return false;
    }
    if (new Date(periodStart) > new Date(periodEnd)) {
      showError('開始日は終了日より前の日付を設定してください');
      return false;
    }
    return true;
  }

  // 個別商品バリデーション
  function validateProductInputs() {
    const productCode = container.querySelector('#product-code').value;
    const currentStock = parseInt(container.querySelector('#current-stock').value);
    const forecastDemand = parseInt(container.querySelector('#forecast-demand').value);
    const safetyStock = parseInt(container.querySelector('#safety-stock').value);
    const leadTime = parseInt(container.querySelector('#lead-time').value);
    const reorderPoint = container.querySelector('#reorder-point').value;

    if (!productCode) {
      showError('商品コードを入力してください');
      return false;
    }
    if (isNaN(currentStock) || currentStock < 0) {
      showError('現在在庫数は0以上の数値を入力してください');
      return false;
    }
    if (isNaN(forecastDemand) || forecastDemand < 0) {
      showError('予測需要量は0以上の数値を入力してください');
      return false;
    }
    if (isNaN(safetyStock) || safetyStock < 0) {
      showError('安全在庫数は0以上の数値を入力してください');
      return false;
    }
    if (isNaN(leadTime) || leadTime <= 0) {
      showError('リードタイムは1以上の値を入力してください');
      return false;
    }
    if (reorderPoint && (isNaN(parseInt(reorderPoint)) || parseInt(reorderPoint) < 0)) {
      showError('発注点は0以上の数値を入力してください');
      return false;
    }
    return true;
  }

  // 計算実行
  container.querySelector('#btn-calculate').addEventListener('click', async () => {
    if (!validateProductInputs()) return;

    const productCode = container.querySelector('#product-code').value;
    const currentStock = parseInt(container.querySelector('#current-stock').value);
    const forecastDemand = parseInt(container.querySelector('#forecast-demand').value);
    const safetyStock = parseInt(container.querySelector('#safety-stock').value);
    const leadTime = parseInt(container.querySelector('#lead-time').value);
    const orderCycle = parseInt(container.querySelector('#order-cycle').value) || 7;
    const reorderPoint = parseInt(container.querySelector('#reorder-point').value) || 0;

    // 商品情報を取得
    const products = await window.aivicApi.list(2); // 商品マスタ
    const product = products?.find(p => p.商品コード === productCode);

    if (!product) {
      showError('指定された商品コードが見つかりません');
      return;
    }

    const recommendedOrder = calculateOrderQuantity(currentStock, forecastDemand, safetyStock, leadTime, orderCycle);

    const result = {
      id: Date.now().toString(),
      productName: product.商品名,
      productCode: productCode,
      currentStock: currentStock,
      forecastDemand: forecastDemand,
      safetyStock: safetyStock,
      reorderPoint: reorderPoint,
      recommendedOrder: recommendedOrder,
      leadTime: leadTime,
      calculatedAt: new Date().toLocaleString('ja-JP')
    };

    calculationResults.unshift(result);
    renderResults(calculationResults);

    // 需要予測結果表示を更新
    const forecastDisplay = container.querySelector('#forecast-display');
    forecastDisplay.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">
        <div>
          <strong>商品名:</strong> ${product.商品名}<br>
          <strong>予測需要:</strong> ${forecastDemand}個
        </div>
        <div>
          <strong>現在在庫:</strong> ${currentStock}個<br>
          <strong>推奨発注量:</strong> <span style="color: var(--primary); font-weight: bold;">${recommendedOrder}個</span>
        </div>
        <div>
          <strong>安全在庫:</strong> ${safetyStock}個<br>
          <strong>リードタイム:</strong> ${leadTime}日
        </div>
      </div>
    `;

    showSuccess('発注量計算が完了しました');
  });

  // 一括計算
  container.querySelector('#btn-bulk-calculate').addEventListener('click', async () => {
    if (!validateInputs()) return;

    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value);
    if (selectedStores.length === 0) {
      showError('一括計算する店舗を選択してください');
      return;
    }

    const category = container.querySelector('#category-select').value;

    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const forecasts = await window.aivicApi.list(8); // 需要予測結果

      if (!products || !stores || !forecasts) {
        showError('データの取得に失敗しました');
        return;
      }

      const categoryProducts = products.filter(p => p.商品カテゴリID === category && p.有効フラグ);
      const bulkResults = [];

      selectedStores.forEach(storeId => {
        const store = stores.find(s => s.店舗ID === storeId);

        categoryProducts.forEach(product => {
          const forecast = forecasts.find(f => 
            f.店舗ID === storeId && f.商品ID === product.商品ID
          );

          if (forecast) {
            const currentStock = Math.floor(Math.random() * 100); // 実際は在庫データから取得
            const recommendedOrder = calculateOrderQuantity(
              currentStock,
              forecast.予測数量 || 0,
              product.最小発注数量 || 10,
              product.リードタイム日数 || 3,
              7
            );

            bulkResults.push({
              id: `${storeId}-${product.商品ID}-${Date.now()}`,
              storeName: store?.店舗名,
              productName: product.商品名,
              productCode: product.商品コード,
              currentStock: currentStock,
              forecastDemand: forecast.予測数量 || 0,
              safetyStock: product.最小発注数量 || 10,
              reorderPoint: Math.floor((forecast.予測数量 || 0) * (product.リードタイム日数 || 3) / 7),
              recommendedOrder: recommendedOrder,
              leadTime: product.リードタイム日数 || 3,
              calculatedAt: new Date().toLocaleString('ja-JP')
            });
          }
        });
      });

      calculationResults = bulkResults.concat(calculationResults);
      renderResults(calculationResults);
      showSuccess(`${selectedStores.length}店舗、${bulkResults.length}商品の一括計算が完了しました`);

    } catch (error) {
      showError('一括計算中にエラーが発生しました');
    }
  });

  // 発注データ生成
  container.querySelector('#btn-generate-order').addEventListener('click', async () => {
    if (calculationResults.length === 0) {
      showError('発注データを生成する計算結果がありません');
      return;
    }

    if (!confirm('計算結果に基づいて発注データを生成しますか？')) return;

    try {
      let generatedCount = 0;

      for (const result of calculationResults) {
        if (result.recommendedOrder > 0) {
          const orderData = {
            店舗ID: result.storeId || container.querySelector('#store-select').value,
            商品ID: result.productId,
            発注日: new Date().toISOString(),
            納期予定日: new Date(Date.now() + (result.leadTime * 24 * 60 * 60 * 1000)).toISOString(),
            発注数量: result.recommendedOrder,
            予測数量: result.forecastDemand,
            発注単価: 100, // 実際は商品マスタから取得
            発注金額: result.recommendedOrder * 100,
            発注方法: 'AI自動発注',
            発注ステータス: '発注済',
            仕入先ID: 'supplier-001',
            発注理由: 'AI需要予測による自動発注',
            自動発注フラグ: true,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'system',
            更新者ID: 'system'
          };

          const saved = await window.aivicApi.save(9, orderData); // 発注データテーブル
          if (saved) generatedCount++;
        }
      }

      showSuccess(`${generatedCount}件の発注データを生成しました`);

      // 発注管理画面に遷移
      setTimeout(() => {
        window.showScreen('scr-1778591852463');
      }, 2000);

    } catch (error) {
      showError('発注データの生成中にエラーが発生しました');
    }
  });

  // 行レベル操作（発注ボタン）
  container.addEventListener('click', async (e) => {
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const resultId = orderBtn.dataset.id;
      const result = calculationResults.find(r => r.id === resultId);

      if (result && confirm(`${result.productName}を${result.recommendedOrder}個発注しますか？`)) {
        // 発注実行画面に遷移
        window.showScreen('scr-1778591960771');
      }
    }
  });

  // 初期化
  initStoreOptions();
  renderResults([]);

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#period-start').value = today;
  container.querySelector('#period-end').value = today;
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const noResults = container.querySelector("#no-results");
  const resultCount = container.querySelector("#result-count");
  const errorMessage = container.querySelector("#error-message");

  // 店舗マスタ、商品マスタのテーブルインデックスを特定
  const storeTableIndex = tables.findIndex(t => t.tableName === "店舗マスタ");
  const productTableIndex = tables.findIndex(t => t.tableName === "商品マスタ");
  const salesTableIndex = tables.findIndex(t => t.tableName === "売上実績データ");

  let allStores = [];
  let allProducts = [];
  let allSales = [];
  let currentInventoryData = [];

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況を判定する関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock <= 0) return "不足";
    if (currentStock < safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫データを生成する関数（商品マスタと売上実績から推定）
  function generateInventoryData(products, sales, storeId) {
    return products.map(product => {
      // 該当店舗・商品の売上実績から在庫を推定
      const productSales = sales.filter(s => s.商品ID === product.商品ID && s.店舗ID === storeId);
      const totalSold = productSales.reduce((sum, s) => sum + (s.販売数量 || 0), 0);

      // 仮の在庫数を計算（実際のシステムでは在庫マスタから取得）
      const estimatedStock = Math.max(0, Math.floor(Math.random() * 200) - totalSold * 0.1);
      const safetyStock = product.最小発注数量 || 10;

      // 最終入荷日を推定
      const lastReceived = productSales.length > 0 
        ? new Date(Math.max(...productSales.map(s => new Date(s.売上日))))
        : new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000);

      return {
        id: `${storeId}-${product.商品ID}`,
        商品ID: product.商品ID,
        商品コード: product.商品コード,
        商品名: product.商品名,
        現在在庫数: estimatedStock,
        安全在庫数: safetyStock,
        在庫状況: getStockStatus(estimatedStock, safetyStock),
        最終入荷日: lastReceived.toISOString().split('T')[0],
        商品カテゴリ: product.商品カテゴリID || "その他"
      };
    });
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.classList.remove("hidden");
      resultCount.textContent = "0件";
      return;
    }

    noResults.classList.add("hidden");
    resultCount.textContent = `${rows.length}件`;

    tbody.innerHTML = rows.map(row => {
      const statusColor = row.在庫状況 === "適正" ? "#4ade80" : 
                         row.在庫状況 === "不足" ? "#f87171" : "#fbbf24";

      return `
        <tr data-id="${row.id}">
          <td>${row.商品コード || ""}</td>
          <td>${row.商品名|| ""}</td>
          <td style="text-align: right;">${row.現在在庫数 || 0}</td>
          <td style="text-align: right;">${row.安全在庫数 || 0}</td>
          <td>
            <span style="display: inline-block; padding: 2px 8px; border-radius: 12px; font-size: 12px; background: ${statusColor}20; color: ${statusColor}; border: 1px solid ${statusColor};">
              ${row.在庫状況}
            </span>
          </td>
          <td>${row.最終入荷日 || ""}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 店舗選択肢を設定
  function loadStores() {
    if (storeTableIndex >= 0) {
      window.aivicApi.list(storeTableIndex).then(stores => {
        if (stores) {
          allStores = stores.filter(s => s.有効フラグ);
          const storeSelect = container.querySelector("#select-store");
          storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
            allStores.map(store => 
              `<option value="${store.店舗ID}">${store.店舗名}</option>`
            ).join("");
        }
      });
    }
  }

  // 商品・売上データを読み込み
  function loadData() {
    const promises = [];

    if (productTableIndex >= 0) {
      promises.push(window.aivicApi.list(productTableIndex));
    } else {
      promises.push(Promise.resolve([]));
    }

    if (salesTableIndex >= 0) {
      promises.push(window.aivicApi.list(salesTableIndex));
    } else {
      promises.push(Promise.resolve([]));
    }

    Promise.all(promises).then(([products, sales]) => {
      allProducts = products || [];
      allSales = sales || [];
    });
  }

  // 検索実行
  function performSearch() {
    const storeId = container.querySelector("#select-store").value;
    const category = container.querySelector("#select-category").value;
    const productName = container.querySelector("#input-product-name").value.trim();
    const productCode = container.querySelector("#input-product-code").value.trim();
    const stockStatus = container.querySelector("#select-stock-status").value;

    // 店舗未選択チェック
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    // 入力値検証
    if (productName && productName.length > 255) {
      showError("商品名は255文字以内で入力してください");
      return;
    }

    if (productCode && !/^[A-Za-z0-9\-_]{1,20}$/.test(productCode)) {
      showError("商品コードは英数字、ハイフン、アンダースコアのみ20文字以内で入力してください");
      return;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|on\w+=/i;
    if (dangerousChars.test(productName) || dangerousChars.test(productCode)) {
      showError("不正な文字が含まれています");
      return;
    }

    // 在庫データを生成
    currentInventoryData = generateInventoryData(allProducts, allSales, storeId);

    // フィルタリング
    let filteredData = currentInventoryData;

    if (category) {
      filteredData = filteredData.filter(item => item.商品カテゴリ === category);
    }

    if (productName) {
      filteredData = filteredData.filter(item => 
        item.商品名.toLowerCase().includes(productName.toLowerCase())
      );
    }

    if (productCode) {
      filteredData = filteredData.filter(item => 
        item.商品コード.toLowerCase().includes(productCode.toLowerCase())
      );
    }

    if (stockStatus) {
      filteredData = filteredData.filter(item => item.在庫状況 === stockStatus);
    }

    renderRows(filteredData);
  }

  // CSVエクスポート
  function exportCSV() {
    if (!currentInventoryData || currentInventoryData.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終入荷日"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...currentInventoryData.map(row => [
        `"${row.商品コード || ""}"`,
        `"${row.商品名 || ""}"`,
        row.現在在庫数 || 0,
        row.安全在庫数 || 0,
        `"${row.在庫状況 || ""}"`,
        `"${row.最終入荷日 || ""}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  loadStores();
  loadData();
  renderRows([]);

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", performSearch);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#select-store").value = "";
    container.querySelector("#select-category").value = "";
    container.querySelector("#input-product-name").value = "";
    container.querySelector("#input-product-code").value = "";
    container.querySelector("#select-stock-status").value = "";
    currentInventoryData = [];
    renderRows([]);
  });

  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 行レベル操作
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const itemId = detailBtn.dataset.id;
      const item = currentInventoryData.find(i => i.id === itemId);
      if (item) {
        alert(`商品詳細\n商品名: ${item.商品名}\n商品コード: ${item.商品コード}\n現在在庫数: ${item.現在在庫数}\n安全在庫数: ${item.安全在庫数}\n在庫状況: ${item.在庫状況}`);
      }
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORE_TABLE = 1;  // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ
  const FORECAST_TABLE = 9; // 需要予測結果
  const ORDER_TABLE = 10; // 発注データ

  let currentForecastData = [];
  let selectedStore = '';
  let orderDate = '';

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 合計金額計算・表示
  function updateTotalAmount() {
    const orderInputs = container.querySelectorAll('.order-quantity-input');
    let total = 0;
    orderInputs.forEach(input => {
      const quantity = parseInt(input.value) || 0;
      const unitPrice = parseInt(input.dataset.unitPrice) || 0;
      total += quantity * unitPrice;
    });
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 発注金額計算
  function calculateOrderAmount(quantity, unitPrice) {
    return (quantity || 0) * (unitPrice || 0);
  }

  // 需要予測結果テーブル描画
  function renderForecastTable(data) {
    const tbody = container.querySelector('#forecast-table-body');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 40px;">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(row => {
      const orderAmount = calculateOrderAmount(row.orderQuantity || 0, row.unitPrice || 0);
      return `
        <tr data-id="${row.id || ''}">
          <td style="color: var(--text);">${row.productCode || ''}</td>
          <td style="color: var(--text);">${row.productName || ''}</td>
          <td style="color: var(--text);">${row.category || ''}</td>
          <td style="color: var(--text); text-align: right;">${(row.forecastQuantity || 0).toLocaleString()}</td>
          <td style="color: var(--text); text-align: right;">${(row.recommendedQuantity || 0).toLocaleString()}</td>
          <td style="color: var(--text); text-align: right;">${(row.currentStock || 0).toLocaleString()}</td>
          <td>
            <input type="number" 
                   class="input order-quantity-input" 
                   value="${row.orderQuantity || 0}" 
                   min="0" 
                   max="999999"
                   data-product-id="${row.productId || ''}"
                   data-unit-price="${row.unitPrice || 0}"
                   style="width: 80px; text-align: right;">
          </td>
          <td style="color: var(--text); text-align: right;">¥${(row.unitPrice || 0).toLocaleString()}</td>
          <td style="color: var(--text); text-align: right;" class="order-amount">¥${orderAmount.toLocaleString()}</td>
          <td>
            <button class="action-btn secondary recommend-btn" data-product-id="${row.productId || ''}">推奨値</button>
          </td>
        </tr>
      `;
    }).join('');

    // 発注数量入力のイベントリスナー
    container.querySelectorAll('.order-quantity-input').forEach(input => {
      input.addEventListener('input', function() {
        const quantity = parseInt(this.value) || 0;
        const unitPrice = parseInt(this.dataset.unitPrice) || 0;
        const orderAmount = calculateOrderAmount(quantity, unitPrice);

        // 行の発注金額を更新
        const row = this.closest('tr');
        row.querySelector('.order-amount').textContent = `¥${orderAmount.toLocaleString()}`;

        // 合計金額を更新
        updateTotalAmount();
      });

      // バリデーション
      input.addEventListener('blur', function() {
        const value = this.value;
        if (value && (isNaN(value) || parseFloat(value) < 0)) {
          showError('発注数量は0以上の数値を入力してください');
          this.focus();
        }
      });
    });

    updateTotalAmount();
  }

  // 店舗選択肢の初期化
  async function initStoreOptions() {
    try {
      const stores = await window.aivicApi.list(STORE_TABLE);
      if (stores) {
        const storeSelect = container.querySelector('#select-store');
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.filter(store => store.有効フラグ).map(store => 
            `<option value="${store.店舗ID}">${store.店舗名}</option>`
          ).join('');
      }
    } catch (error) {
      console.error('店舗データ取得エラー:', error);
    }
  }

  // 需要予測データ取得・表示
  async function loadForecastData() {
    const storeId = container.querySelector('#select-store').value;
    const orderDate = container.querySelector('#input-order-date').value;
    const category = container.querySelector('#select-category').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    // 過去日付チェック
    const today = new Date().toISOString().split('T')[0];
    if (orderDate < today) {
      showError('発注日付には本日以降の日付を選択してください');
      return;
    }

    try {
      // 需要予測結果を取得
      const forecasts = await window.aivicApi.list(FORECAST_TABLE);
      const products = await window.aivicApi.list(PRODUCT_TABLE);

      if (forecasts && products) {
        // 店舗・日付でフィルタリング
        let filteredForecasts = forecasts.filter(f => 
          f.店舗ID === storeId && 
          f.予測対象日 && 
          f.予測対象日.split('T')[0] === orderDate
        );

        // カテゴリフィルタリング
        if (category) {
          const categoryProducts = products.filter(p => p.商品カテゴリID === category);
          const categoryProductIds = categoryProducts.map(p => p.商品ID);
          filteredForecasts = filteredForecasts.filter(f => 
            categoryProductIds.includes(f.商品ID)
          );
        }

        // 商品情報とマージ
        currentForecastData = filteredForecasts.map(forecast => {
          const product = products.find(p => p.商品ID === forecast.商品ID);
          return {
            id: forecast.予測結果ID,
            productId: forecast.商品ID,
            productCode: product?.商品コード || '',
            productName: product?.商品名 || '',
            category: product?.商品カテゴリID || '',
            forecastQuantity: forecast.予測数量,
            recommendedQuantity: forecast.推奨発注数量,
            currentStock: Math.floor(Math.random() * 100), // サンプル在庫数
            orderQuantity: 0,
            unitPrice: product?.単価 || 0
          };
        });

        renderForecastTable(currentForecastData);
        selectedStore = storeId;
        window.orderDate = orderDate;
      }
    } catch (error) {
      console.error('予測データ取得エラー:', error);
      showError('予測データの取得に失敗しました');
    }
  }

  // 推奨発注数量で一括入力
  function bulkSetRecommended() {
    if (!confirm('全ての商品の発注数量を推奨値に設定しますか？')) return;

    const inputs = container.querySelectorAll('.order-quantity-input');
    inputs.forEach(input => {
      const productId = input.dataset.productId;
      const forecastItem = currentForecastData.find(item => item.productId === productId);
      if (forecastItem) {
        input.value = forecastItem.recommendedQuantity || 0;
        input.dispatchEvent(new Event('input'));
      }
    });
  }

  // 発注承認処理
  function showApprovalDialog() {
    const orderItems = [];
    const inputs = container.querySelectorAll('.order-quantity-input');

    inputs.forEach(input => {
      const quantity = parseInt(input.value) || 0;
      if (quantity > 0) {
        const productId = input.dataset.productId;
        const forecastItem = currentForecastData.find(item => item.productId === productId);
        if (forecastItem) {
          orderItems.push({
            ...forecastItem,
            orderQuantity: quantity,
            orderAmount: calculateOrderAmount(quantity, forecastItem.unitPrice)
          });
        }
      }
    });

    if (orderItems.length === 0) {
      showError('発注数量が入力された商品がありません');
      return;
    }

    // 承認ダイアログの内容を生成
    const totalAmount = orderItems.reduce((sum, item) => sum + item.orderAmount, 0);
    const approvalContent = container.querySelector('#approval-content');
    approvalContent.innerHTML = `
      <div style="margin-bottom: 16px;">
        <strong style="color: var(--text);">発注先店舗:</strong> 
        <span style="color: var(--text);">${container.querySelector('#select-store option:checked').textContent}</span>
      </div>
      <div style="margin-bottom: 16px;">
        <strong style="color: var(--text);">発注日付:</strong> 
        <span style="color: var(--text);">${container.querySelector('#input-order-date').value}</span>
      </div>
      <div style="margin-bottom: 16px;">
        <strong style="color: var(--text);">発注商品数:</strong> 
        <span style="color: var(--text);">${orderItems.length}件</span>
      </div>
      <div style="margin-bottom: 16px;">
        <strong style="color: var(--text);">合計金額:</strong> 
        <span style="color: var(--text);">¥${totalAmount.toLocaleString()}</span>
      </div>
      <div class="table-wrap" style="max-height: 300px; overflow-y: auto;">
        <table>
          <thead>
            <tr>
              <th style="color: var(--text);">商品名</th>
              <th style="color: var(--text);">発注数量</th>
              <th style="color: var(--text);">単価</th>
              <th style="color: var(--text);">金額</th>
            </tr>
          </thead>
          <tbody>
            ${orderItems.map(item => `
              <tr>
                <td style="color: var(--text);">${item.productName}</td>
                <td style="color: var(--text); text-align: right;">${item.orderQuantity.toLocaleString()}</td>
                <td style="color: var(--text); text-align: right;">¥${item.unitPrice.toLocaleString()}</td>
                <td style="color: var(--text); text-align: right;">¥${item.orderAmount.toLocaleString()}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;

    container.querySelector('#approval-dialog').classList.remove('hidden');
  }

  // 発注実行
  async function executeOrder() {
    const orderItems = [];
    const inputs = container.querySelectorAll('.order-quantity-input');

    inputs.forEach(input => {
      const quantity = parseInt(input.value) || 0;
      if (quantity >= 0) { // 0でも承認可能
        const productId = input.dataset.productId;
        const forecastItem = currentForecastData.find(item => item.productId === productId);
        if (forecastItem) {
          orderItems.push({
            店舗ID: selectedStore,
            商品ID: productId,
            需要予測結果ID: forecastItem.id,
            発注日: new Date(window.orderDate).toISOString(),
            納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
            発注数量: quantity,
            予測数量: forecastItem.recommendedQuantity,
            発注単価: forecastItem.unitPrice,
            発注金額: calculateOrderAmount(quantity, forecastItem.unitPrice),
            発注方法: 'AI推奨採用',
            発注ステータス: '承認済み',
            仕入先ID: 'supplier-001',
            発注理由: 'AI需要予測に基づく発注',
            承認者ID: 'current-user-id',
            承認日時: new Date().toISOString(),
            自動発注フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'current-user-id',
            更新者ID: 'current-user-id'
          });
        }
      }
    });

    try {
      // 各発注データを保存
      for (const orderItem of orderItems) {
        await window.aivicApi.save(ORDER_TABLE, orderItem);
      }

      // 成功メッセージ
      alert(`発注が正常に完了しました。\n発注件数: ${orderItems.length}件`);

      // ダイアログを閉じる
      container.querySelector('#approval-dialog').classList.add('hidden');

      // 発注管理画面に遷移
      window.showScreen('scr-1778591852463');

    } catch (error) {
      console.error('発注実行エラー:', error);
      showError('発注の実行に失敗しました');
