        productName: `サンプル商品${index + 1}`,
        category: ['食品', '飲料', '日用品'][index % 3],
        forecastQuantity: Math.floor(Math.random() * 100) + 50,
        recommendedQuantity: Math.floor(Math.random() * 80) + 30,
        currentStock: Math.floor(Math.random() * 50) + 10,
