  // イベントリスナー登録
  container.querySelector('#btn-display').addEventListener('click', loadForecastData);
  container.querySelector('#btn-update-forecast').addEventListener('click', loadForecastData);
  container.querySelector('#btn-bulk-recommend').addEventListener('click', bulkSetRecommended);
  container.querySelector('#btn-approve-order').addEventListener('click', showApprovalDialog);
  container.querySelector('#btn-cancel-approval').addEventListener('click', () => {
    container.querySelector('#approval-dialog').classList.add('hidden');
  });
  container.querySelector('#btn-confirm-approval').addEventListener('click', executeOrder);

  // 推奨値ボタンのイベントデリゲーション
  container.addEventListener('click', (e) => {
    const recommendBtn = e.target.closest('.recommend-btn');
    if (recommendBtn) {
      const productId = recommendBtn.dataset.productId;
      const forecastItem = currentForecastData.find(item => item.productId === productId);
      if (forecastItem) {
        const input = container.querySelector(`input[data-product-id="${productId}"]`);
        if (input) {
          input.value = forecastItem.recommendedQuantity || 0;
          input.dispatchEvent(new Event('input'));
