  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = 'accuracy';
  let sortDirection = 'desc';
  let chartPeriod = 'daily';

  // 店舗選択の初期化
  function initStoreFilter() {
    const storeFilter = container.querySelector('#store-filter');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeFilter.appendChild(option);
    });
  }

  // 精度データの計算
  function calculateAccuracyMetrics(predictions) {
    if (!predictions.length) return { avgAccuracy: 0, mape: 0, rmse: 0, count: 0 };

    let totalAccuracy = 0;
    let totalMape = 0;
    let totalRmse = 0;
    let validCount = 0;

    predictions.forEach(pred => {
      const predicted = pred.予測数量 || 0;
      const actual = pred.実績数量 || 0;

      if (actual > 0) {
        const accuracy = Math.max(0, 100 - Math.abs((predicted - actual) / actual * 100));
        const ape = Math.abs((predicted - actual) / actual * 100);
        const se = Math.pow(predicted - actual, 2);

        totalAccuracy += accuracy;
        totalMape += ape;
        totalRmse += se;
        validCount++;
      }
    });

    return {
      avgAccuracy: validCount > 0 ? (totalAccuracy / validCount).toFixed(1) : 0,
      mape: validCount > 0 ? (totalMape / validCount).toFixed(2) : 0,
      rmse: validCount > 0 ? Math.sqrt(totalRmse / validCount).toFixed(2) : 0,
      count: validCount
    };
  }

  // サマリーカードの更新
  function updateSummaryCards(data) {
    const metrics = calculateAccuracyMetrics(data);

    container.querySelector('#avg-accuracy').textContent = metrics.avgAccuracy + '%';
    container.querySelector('#mape-value').textContent = metrics.mape + '%';
    container.querySelector('#rmse-value').textContent = metrics.rmse;
    container.querySelector('#data-count').textContent = metrics.count + '件';

    // アラート表示判定
    const alertPanel = container.querySelector('#alert-panel');
    const alertContent = container.querySelector('#alert-content');

    if (parseFloat(metrics.avgAccuracy) < 80) {
      alertContent.innerHTML = `
        <p>予測精度が閾値(80%)を下回りました</p>
        <p>現在の平均精度: ${metrics.avgAccuracy}% (${new Date().toLocaleString()})</p>
      `;
      alertPanel.style.display = 'block';
    } else {
      alertPanel.style.display = 'none';
    }
  }

  // 予測精度推移グラフの描画
  function drawAccuracyChart(data) {
    const canvas = container.querySelector('#accuracy-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = { top: 20, right: 20, bottom: 40, left: 60 };

    // 背景クリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, width, height);

    if (!data.length) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', width / 2, height / 2);
      return;
    }

    // データの期間別集計
    const groupedData = {};
    data.forEach(item => {
      const date = new Date(item.予測対象日);
      let key;

      if (chartPeriod === 'daily') {
        key = date.toISOString().split('T')[0];
      } else if (chartPeriod === 'weekly') {
        const weekStart = new Date(date);
        weekStart.setDate(date.getDate() - date.getDay());
        key = weekStart.toISOString().split('T')[0];
      } else {
        key = date.getFullYear() + '-' + String(date.getMonth() + 1).padStart(2, '0');
      }

      if (!groupedData[key]) {
        groupedData[key] = { predictions: [], date: key };
      }
      groupedData[key].predictions.push(item);
    });

    const chartData = Object.values(groupedData).map(group => {
      const metrics = calculateAccuracyMetrics(group.predictions);
      return {
        date: group.date,
        accuracy: parseFloat(metrics.avgAccuracy)
      };
    }).sort((a, b) => a.date.localeCompare(b.date));

    if (!chartData.length) return;

    // グラフ描画エリア
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    // Y軸（0-100%）
    ctx.strokeStyle = '#3a4a5c';
    ctx.lineWidth = 1;

    for (let i = 0; i <= 10; i++) {
      const y = padding.top + (chartHeight * i / 10);
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px Arial';
      ctx.textAlign = 'right';
      ctx.fillText((100 - i * 10) + '%', padding.left - 5, y + 4);
    }

    // X軸
    const xStep = chartWidth / (chartData.length - 1 || 1);
    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);

      ctx.strokeStyle = '#3a4a5c';
      ctx.beginPath();
      ctx.moveTo(x, padding.top);
      ctx.lineTo(x, height - padding.bottom);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';
      const label = chartPeriod === 'monthly' ? item.date : item.date.split('-').slice(1).join('/');
      ctx.fillText(label, x, height - padding.bottom + 15);
    });

    // 精度ライン描画
    ctx.strokeStyle = '#4fc3f7';
    ctx.lineWidth = 2;
    ctx.beginPath();

    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);
      const y = padding.top + (chartHeight * (100 - item.accuracy) / 100);

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // データポイント
    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);
      const y = padding.top + (chartHeight * (100 - item.accuracy) / 100);

      ctx.fillStyle = '#4fc3f7';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();
    });
  }

  // 予測vs実績比較チャートの描画
  function drawComparisonChart(data) {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = { top: 20, right: 20, bottom: 40, left: 60 };

    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, width, height);

    if (!data.length) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', width / 2, height / 2);
      return;
    }

    const chartData = data.filter(item => item.実績数量 != null).slice(0, 30);
    if (!chartData.length) return;

    const maxValue = Math.max(...chartData.map(item => Math.max(item.予測数量 || 0, item.実績数量 || 0)));
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    // Y軸
    ctx.strokeStyle = '#3a4a5c';
    ctx.lineWidth = 1;

    for (let i = 0; i <= 5; i++) {
      const y = padding.top + (chartHeight * i / 5);
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px Arial';
      ctx.textAlign = 'right';
      ctx.fillText(Math.round(maxValue * (5 - i) / 5), padding.left - 5, y + 4);
    }

    // X軸とデータ描画
    const xStep = chartWidth / (chartData.length - 1 || 1);

    // 予測値ライン
    ctx.strokeStyle = '#ff9800';
    ctx.lineWidth = 2;
    ctx.beginPath();
    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);
      const y = padding.top + (chartHeight * (maxValue - (item.予測数量 || 0)) / maxValue);
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 実績値ライン
    ctx.strokeStyle = '#4caf50';
    ctx.lineWidth = 2;
    ctx.beginPath();
    chartData.forEach((item, index) => {
      const x = padding.left + (index * xStep);
      const y = padding.top + (chartHeight * (maxValue - (item.実績数量 || 0)) / maxValue);
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#ff9800';
    ctx.fillRect(width - 150, 20, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', width - 130, 32);

    ctx.fillStyle = '#4caf50';
    ctx.fillRect(width - 150, 40, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績値', width - 130, 52);
  }

  // ランキングテーブルの描画
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');

    if (!data.length) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    // 店舗・商品別に集計
    const aggregated = {};
    data.forEach(item => {
      const key = `${item.店舗ID}_${item.商品ID}`;
      if (!aggregated[key]) {
        aggregated[key] = {
          store_id: item.店舗ID,
          product_id: item.商品ID,
          predictions: []
        };
      }
      aggregated[key].predictions.push(item);
    });

    const rankingData = Object.values(aggregated).map(group => {
      const metrics = calculateAccuracyMetrics(group.predictions);
      const store = tables[1]?.records?.find(s => s.店舗ID === group.store_id);
      const product = tables[2]?.records?.find(p => p.商品ID === group.product_id);

      return {
        store_name: store?.店舗名 || '不明',
        product_name: product?.商品名 || '不明',
        category: product?.商品カテゴリID || '不明',
        accuracy: parseFloat(metrics.avgAccuracy),
        mape: parseFloat(metrics.mape),
        rmse: parseFloat(metrics.rmse),
        prediction_count: group.predictions.length
      };
    });

    // ソート
    rankingData.sort((a, b) => {
      const aVal = a[sortColumn];
      const bVal = b[sortColumn];
      const multiplier = sortDirection === 'asc' ? 1 : -1;
      return (aVal > bVal ? 1 : -1) * multiplier;
    });

    tbody.innerHTML = rankingData.map((item, index) => {
      const rank = index + 1;
      const statusClass = item.accuracy >= 90 ? 'excellent' : item.accuracy >= 80 ? 'good' : item.accuracy >= 70 ? 'fair' : 'poor';
      const statusText = item.accuracy >= 90 ? '優秀' : item.accuracy >= 80 ? '良好' : item.accuracy >= 70 ? '普通' : '要改善';
      const statusColor = item.accuracy >= 90 ? '#4caf50' : item.accuracy >= 80 ? '#2196f3' : item.accuracy >= 70 ? '#ff9800' : '#f44336';

      return `
        <tr>
          <td>${rank}</td>
          <td>${item.store_name}</td>
          <td>${item.product_name}</td>
          <td>${item.category}</td>
          <td style="font-weight: bold;">${item.accuracy.toFixed(1)}%</td>
          <td>${item.mape.toFixed(2)}%</td>
          <td>${item.rmse.toFixed(2)}</td>
          <td>${item.prediction_count}</td>
          <td><span style="color: ${statusColor}; font-weight: bold;">${statusText}</span></td>
        </tr>
      `;
    }).join('');
  }

  // データのフィルタリング
  function filterData() {
    const period = parseInt(container.querySelector('#period-filter').value);
    const storeId = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;
    const accuracyThreshold = container.querySelector('#accuracy-filter').value;

    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - period);

    let filtered = currentData.filter(item => {
      const itemDate = new Date(item.予測対象日);
      return itemDate >= cutoffDate;
    });

    if (storeId) {
      filtered = filtered.filter(item => item.店舗ID === storeId);
    }

    if (category) {
      const products = tables[2]?.records?.filter(p => p.商品カテゴリID === category) || [];
      const productIds = products.map(p => p.商品ID);
      filtered = filtered.filter(item => productIds.includes(item.商品ID));
    }

    if (accuracyThreshold) {
      filtered = filtered.filter(item => {
        if (!item.実績数量 || item.実績数量 === 0) return false;
        const accuracy = Math.max(0, 100 - Math.abs((item.予測数量 - item.実績数量) / item.実績数量 * 100));
        return accuracy >= parseFloat(accuracyThreshold);
      });
    }

    return filtered;
  }

  // 画面更新
  function updateScreen() {
    const filteredData = filterData();
    updateSummaryCards(filteredData);
    drawAccuracyChart(filteredData);
    drawComparisonChart(filteredData);
    renderRankingTable(filteredData);
  }

  // 初期化
  initStoreFilter();

  // 初期データ読み込み
  window.aivicApi.list(4).then(rows => {
    if (rows) {
      currentData = rows;
      updateScreen();
    }
  });

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', updateScreen);
  container.querySelector('#btn-refresh').addEventListener('click', () => {
    window.aivicApi.list(4).then(rows => {
      if (rows) {
        currentData = rows;
        updateScreen();
      }
    });
  });

  // チャート期間切り替え
  container.addEventListener('click', e => {
    const periodBtn = e.target.closest('.chart-period-btn');
    if (periodBtn) {
      container.querySelectorAll('.chart-period-btn').forEach(btn => btn.classList.remove('active'));
      periodBtn.classList.add('active');
      chartPeriod = periodBtn.dataset.period;
      const filteredData = filterData();
      drawAccuracyChart(filteredData);
    }
  });

  // テーブルソート
  container.addEventListener('click', e => {
    const sortBtn = e.target.closest('.sortable');
    if (sortBtn) {
      const column = sortBtn.dataset.sort;
      if (sortColumn === column) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        sortColumn = column;
        sortDirection = 'desc';
      }

      // ソート表示更新
      container.querySelectorAll('.sortable').forEach(th => {
        th.style.background = 'var(--bg-card)';
      });
      sortBtn.style.background = 'var(--primary)';

      const filteredData = filterData();
      renderRankingTable(filteredData);
    }
  });

  // 詳細分析ボタン
  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591822586'); // 相関分析・比較分析画面
  });

  // レポート出力ボタン
  container.querySelector('#btn-export-report').addEventListener('click', () => {
    try {
      const filteredData = filterData();
      const metrics = calculateAccuracyMetrics(filteredData);

      const reportData = [
        ['予測精度監視レポート', '', '', '', '', ''],
        ['出力日時', new Date().toLocaleString(), '', '', '', ''],
        ['', '', '', '', '', ''],
        ['サマリー', '', '', '', '', ''],
        ['平均予測精度', metrics.avgAccuracy + '%', '', '', '', ''],
        ['MAPE', metrics.mape + '%', '', '', '', ''],
        ['RMSE', metrics.rmse, '', '', '', ''],
        ['対象データ数', metrics.count + '件', '', '', '', ''],
        ['', '', '', '', '', ''],
        ['詳細データ', '', '', '', '', ''],
        ['店舗名', '商品名', 'カテゴリ', '予測精度', 'MAPE', 'RMSE']
      ];

      // ランキングデータを追加
      const aggregated = {};
      filteredData.forEach(item => {
        const key = `${item.店舗ID}_${item.商品ID}`;
        if (!aggregated[key]) {
          aggregated[key] = {
            store_id: item.店舗ID,
            product_id: item.商品ID,
            predictions: []
          };
        }
        aggregated[key].predictions.push(item);
      });

      Object.values(aggregated).forEach(group => {
        const groupMetrics = calculateAccuracyMetrics(group.predictions);
        const store = tables[1]?.records?.find(s => s.店舗ID === group.store_id);
        const product = tables[2]?.records?.find(p => p.商品ID === group.product_id);

        reportData.push([
          store?.店舗名 || '不明',
          product?.商品名 || '不明',
          product?.商品カテゴリID || '不明',
          groupMetrics.avgAccuracy + '%',
          groupMetrics.mape + '%',
          groupMetrics.rmse
        ]);
      });

      const csvContent = '\uFEFF' + reportData.map(row => 
        row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
      ).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `予測精度監視レポート_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      alert('レポート出力に失敗しました: ' + error.message);
    }
  });
}

function(container, apiUrl, tables) {
  let currentTestId = null;
  let testResults = null;

  // 店舗一覧を描画
  function renderStores() {
    const storeList = container.querySelector("#store-list");
    const stores = tables[1]?.records || [];

    storeList.innerHTML = stores.map(store => `
      <label style="display: block; margin-bottom: 8px;">
        <input type="checkbox" class="store-checkbox" value="${store.id}" style="margin-right: 8px;">
        ${store.店舗名} (${store.店舗コード})
      </label>
    `).join("");
  }

  // テスト履歴を描画
  function renderTestHistory() {
    const tbody = container.querySelector("#history-tbody");
    // サンプルデータとして表示
    const sampleHistory = [
      {
        id: "test-1",
        実行日時: "2024-01-15 14:30:00",
        モデル名: "需要予測モデル v1.0",
        テスト期間: "2024-01-01 ～ 2024-01-14",
        対象店舗数: 5,
        MAPE: 12.5,
        RMSE: 8.3,
        実行時間: 45,
        ステータス: "完了"
      },
      {
        id: "test-2", 
        実行日時: "2024-01-10 09:15:00",
        モデル名: "需要予測モデル v1.1",
        テスト期間: "2023-12-15 ～ 2024-01-09",
        対象店舗数: 3,
        MAPE: 15.2,
        RMSE: 9.7,
        実行時間: 32,
        ステータス: "完了"
      }
    ];

    tbody.innerHTML = sampleHistory.map(test => `
      <tr data-id="${test.id}">
        <td>${test.実行日時}</td>
        <td>${test.モデル名}</td>
        <td>${test.テスト期間}</td>
        <td>${test.対象店舗数}</td>
        <td>${test.MAPE}%</td>
        <td>${test.RMSE}</td>
        <td>${test.実行時間}</td>
        <td><span style="padding: 4px 8px; background: #28a745; color: white; border-radius: 4px; font-size: 12px;">${test.ステータス}</span></td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${test.id}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  // グラフを描画
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const actualData = [120, 135, 98, 156, 142, 178, 165, 189, 203, 187, 165, 145, 132, 148];
    const predictedData = [115, 128, 105, 162, 138, 172, 158, 195, 198, 182, 170, 152, 128, 143];
    const labels = ["1日", "2日", "3日", "4日", "5日", "6日", "7日", "8日", "9日", "10日", "11日", "12日", "13日", "14日"];

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データの最大値・最小値を計算
    const allData = [...actualData, ...predictedData];
    const maxValue = Math.max(...allData);
    const minValue = Math.min(...allData);
    const valueRange = maxValue - minValue;

    // 実績値の線を描画
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (actualData.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((actualData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.stroke();

    // 予測値の線を描画
    ctx.strokeStyle = '#007bff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (i / (predictedData.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((predictedData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.stroke();

    // 凡例を描画
    ctx.fillStyle = '#ff6a00';
    ctx.fillRect(padding, 20, 20, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', padding + 30, 30);

    ctx.fillStyle = '#007bff';
    ctx.fillRect(padding + 100, 20, 20, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測値', padding + 130, 30);
  }

  // テスト実行のシミュレーション
  function executeTest() {
    const modelSelect = container.querySelector("#model-select");
    const startDate = container.querySelector("#start-date");
    const endDate = container.querySelector("#end-date");
    const categorySelect = container.querySelector("#category-select");
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');

    // バリデーション
    if (!modelSelect.value) {
      alert("予測モデルが選択されていません");
      return;
    }
    if (!selectedDataset) {
      alert("テストデータセットが選択されていません");
      return;
    }
    if (!startDate.value || !endDate.value) {
      alert("テスト期間を設定してください");
      return;
    }
    if (new Date(endDate.value) < new Date(startDate.value)) {
      alert("終了日は開始日より後の日付を設定してください");
      return;
    }
    if (selectedStores.length === 0) {
      alert("対象店舗を選択してください");
      return;
    }
    if (!categorySelect.value) {
      alert("商品カテゴリが未選択です");
      return;
    }

    // プログレス表示
    const progressDiv = container.querySelector("#test-progress");
    const resultsDiv = container.querySelector("#test-results");
    const progressBar = container.querySelector("#progress-bar");
    const progressText = container.querySelector("#progress-text");

    progressDiv.classList.remove("hidden");
    resultsDiv.classList.add("hidden");

    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 100) progress = 100;

      progressBar.style.width = progress + "%";
      progressText.textContent = Math.round(progress) + "%";

      if (progress >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          showTestResults();
          progressDiv.classList.add("hidden");
        }, 500);
      }
    }, 200);
  }

  // テスト結果を表示
  function showTestResults() {
    const resultsDiv = container.querySelector("#test-results");
    const mapeValue = container.querySelector("#mape-value");
    const rmseValue = container.querySelector("#rmse-value");
    const executionTime = container.querySelector("#execution-time");
    const modelParameters = container.querySelector("#model-parameters");

    // サンプル結果データ
    const results = {
      mape: (Math.random() * 20 + 5).toFixed(1),
      rmse: (Math.random() * 15 + 5).toFixed(1),
      executionTime: Math.round(Math.random() * 60 + 20),
      parameters: {
        "学習率": "0.001",
        "バッチサイズ": "32",
        "エポック数": "100",
        "隠れ層数": "3",
        "ドロップアウト率": "0.2"
      }
    };

    testResults = results;

    mapeValue.textContent = results.mape;
    rmseValue.textContent = results.rmse;
    executionTime.textContent = results.executionTime;

    modelParameters.innerHTML = Object.entries(results.parameters)
      .map(([key, value]) => `<div style="margin-bottom: 8px;"><strong>${key}:</strong> ${value}</div>`)
      .join("");

    resultsDiv.classList.remove("hidden");
    drawComparisonChart();
  }

  // 結果エクスポート
  function exportResults() {
    if (!testResults) {
      alert("エクスポートするテスト結果がありません");
      return;
    }

    const csvContent = [
      "項目,値",
      `MAPE (%),${testResults.mape}`,
      `RMSE,${testResults.rmse}`,
      `実行時間 (秒),${testResults.executionTime}`,
      "",
      "モデルパラメータ,",
      ...Object.entries(testResults.parameters).map(([key, value]) => `${key},${value}`)
    ].join("\n");

    const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `model_test_results_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  renderStores();
  renderTestHistory();

  // 全店舗選択チェックボックス
  container.querySelector("#select-all-stores").addEventListener("change", function() {
    const checkboxes = container.querySelectorAll(".store-checkbox");
    checkboxes.forEach(cb => cb.checked = this.checked);
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", executeTest);

  // 結果エクスポートボタン
  container.querySelector("#btn-export-results").addEventListener("click", exportResults);

  // 履歴詳細表示
  container.addEventListener("click", function(e) {
    const detailBtn = e.target.closest(".view-detail-btn");
    if (detailBtn) {
      const testId = detailBtn.dataset.id;
      alert(`テスト詳細: ${testId}\n（詳細画面への遷移機能は今後実装予定）`);
    }
  });
}

function(container, apiUrl, tables) {
  let currentApplyProcess = null;
  let selectedStores = new Set();
  let availableModels = [];
  let currentModelDetails = null;

  // 初期化
  async function init() {
    await loadModels();
    await loadStores();
    setDefaultDateTime();
    setupEventListeners();
  }

  // モデル一覧を読み込み
  async function loadModels() {
    // 検証済みモデルのみを表示（実際のAPIでは検証ステータスでフィルタ）
    availableModels = [
      { id: '1', name: 'AI需要予測モデル v2.1', status: '検証完了', accuracy: 95.2, version: 'v2.1' },
      { id: '2', name: 'AI需要予測モデル v2.0', status: '検証完了', accuracy: 93.8, version: 'v2.0' },
      { id: '3', name: 'AI需要予測モデル v1.9', status: '検証中', accuracy: 92.1, version: 'v1.9' }
    ];

    const modelSelect = container.querySelector('#select-model');
    modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>';

    availableModels.filter(m => m.status === '検証完了').forEach(model => {
      const option = document.createElement('option');
      option.value = model.id;
      option.textContent = `${model.name} (精度: ${model.accuracy}%)`;
      modelSelect.appendChild(option);
    });
  }

  // 店舗一覧を読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1) || [];
    const storeList = container.querySelector('#store-list');

    storeList.innerHTML = stores.map(store => `
      <label style="display: block; margin-bottom: 5px; color: var(--text);">
        <input type="checkbox" class="store-checkbox" value="${store.id}">
        ${store.店舗名} (${store.店舗コード})
      </label>
    `).join('');
  }

  // デフォルト日時設定
  function setDefaultDateTime() {
    const now = new Date();
    now.setMinutes(now.getMinutes() + 10); // 10分後をデフォルト
    const datetime = now.toISOString().slice(0, 16);
    container.querySelector('#apply-datetime').value = datetime;
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // モデル選択時
    container.querySelector('#select-model').addEventListener('change', onModelSelect);

    // 全店舗選択
    container.querySelector('#select-all-stores').addEventListener('change', onSelectAllStores);

    // 店舗選択
    container.addEventListener('change', (e) => {
      if (e.target.classList.contains('store-checkbox')) {
        onStoreSelect();
      }
    });

    // 適用実行ボタン
    container.querySelector('#btn-apply').addEventListener('click', onApplyClick);

    // 一括適用ボタン
    container.querySelector('#btn-batch-apply').addEventListener('click', onBatchApplyClick);

    // ロールバックボタン
    container.querySelector('#btn-rollback').addEventListener('click', onRollbackClick);

    // ダイアログ
    container.querySelector('#dialog-ok').addEventListener('click', onDialogOk);
    container.querySelector('#dialog-cancel').addEventListener('click', hideDialog);
  }

  // モデル選択時の処理
  function onModelSelect() {
    const modelId = container.querySelector('#select-model').value;
    const model = availableModels.find(m => m.id === modelId);

    if (model) {
      currentModelDetails = model;
      showModelDetails(model);
      showValidationResults(model);
      updateImpactRange();
    } else {
      hideModelDetails();
      hideValidationResults();
      hideImpactRange();
    }
  }

  // モデル詳細表示
  function showModelDetails(model) {
    const detailsDiv = container.querySelector('#model-details');
    const infoDiv = container.querySelector('#model-info');

    infoDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
        <div>
          <strong>モデル名:</strong> ${model.name}<br>
          <strong>バージョン:</strong> ${model.version}<br>
          <strong>検証ステータス:</strong> <span style="color: #4CAF50;">${model.status}</span>
        </div>
        <div>
          <strong>予測精度:</strong> ${model.accuracy}%<br>
          <strong>作成日:</strong> 2024-01-15<br>
          <strong>最終更新:</strong> 2024-01-20
        </div>
      </div>
    `;

    detailsDiv.style.display = 'block';
  }

  // モデル詳細非表示
  function hideModelDetails() {
    container.querySelector('#model-details').style.display = 'none';
  }

  // 検証結果表示
  function showValidationResults(model) {
    const resultsDiv = container.querySelector('#validation-results');
    const infoDiv = container.querySelector('#validation-info');

    infoDiv.innerHTML = `
      <div style="color: #4CAF50; margin-bottom: 10px;">✓ 検証完了</div>
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
        <div>
          <strong>テストデータ精度:</strong> ${model.accuracy}%<br>
          <strong>検証期間:</strong> 2024-01-01 ～ 2024-01-14<br>
          <strong>検証データ件数:</strong> 10,000件
        </div>
        <div>
          <strong>平均誤差率:</strong> 4.8%<br>
          <strong>最大誤差率:</strong> 12.3%<br>
          <strong>検証完了日:</strong> 2024-01-20
        </div>
      </div>
    `;

    resultsDiv.style.display = 'block';
  }

  // 検証結果非表示
  function hideValidationResults() {
    container.querySelector('#validation-results').style.display = 'none';
  }

  // 全店舗選択
  function onSelectAllStores() {
    const selectAll = container.querySelector('#select-all-stores').checked;
    const checkboxes = container.querySelectorAll('.store-checkbox');

    checkboxes.forEach(cb => {
      cb.checked = selectAll;
    });

    onStoreSelect();
  }

  // 店舗選択時の処理
  function onStoreSelect() {
    const checkboxes = container.querySelectorAll('.store-checkbox:checked');
    selectedStores.clear();

    checkboxes.forEach(cb => {
      selectedStores.add(cb.value);
    });

    updateImpactRange();
  }

  // 影響範囲更新
  function updateImpactRange() {
    if (selectedStores.size === 0 || !currentModelDetails) {
      hideImpactRange();
      return;
    }

    const impactDiv = container.querySelector('#impact-range');
    const infoDiv = container.querySelector('#impact-info');

    const estimatedTime = Math.ceil(selectedStores.size * 2); // 1店舗あたり2分と仮定

    infoDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
        <div>
          <strong>対象店舗数:</strong> ${selectedStores.size}店舗<br>
          <strong>影響商品カテゴリ:</strong> 全カテゴリ<br>
          <strong>予想処理時間:</strong> 約${estimatedTime}分
        </div>
        <div>
          <strong>影響する予測データ:</strong> 約${selectedStores.size * 1000}件<br>
          <strong>バックアップサイズ:</strong> 約${Math.ceil(selectedStores.size * 0.5)}MB<br>
          <strong>ダウンタイム:</strong> なし
        </div>
      </div>
      ${selectedStores.size > 10 ? '<div style="color: #ff9800; margin-top: 10px;">⚠ 大規模適用のため、処理に時間がかかる場合があります</div>' : ''}
    `;

    impactDiv.style.display = 'block';
  }

  // 影響範囲非表示
  function hideImpactRange() {
    container.querySelector('#impact-range').style.display = 'none';
  }

  // 適用実行
  function onApplyClick() {
    if (!validateInputs()) return;

    showConfirmDialog(
      'モデル本番適用確認',
      `選択したモデルを${selectedStores.size}店舗に適用します。よろしいですか？`,
      () => executeApply(false)
    );
  }

  // 一括適用
  function onBatchApplyClick() {
    if (!validateInputs()) return;

    showConfirmDialog(
      '一括適用確認',
      `選択したモデルを${selectedStores.size}店舗に一括適用します。処理に時間がかかる場合があります。よろしいですか？`,
      () => executeApply(true)
    );
  }

  // 入力値検証
  function validateInputs() {
    const modelId = container.querySelector('#select-model').value;
    const applyDateTime = container.querySelector('#apply-datetime').value;
    const retentionDays = parseInt(container.querySelector('#retention-days').value);

    if (!modelId) {
      alert('適用対象のモデルが選択されていません');
      return false;
    }

    const model = availableModels.find(m => m.id === modelId);
    if (!model || model.status !== '検証完了') {
      alert('検証が完了していないモデルは本番適用できません');
      return false;
    }

    if (selectedStores.size === 0) {
      alert('店舗が選択されていません');
      return false;
    }

    if (!applyDateTime) {
      alert('適用開始日時を入力してください');
      return false;
    }

    const applyDate = new Date(applyDateTime);
    const now = new Date();
    if (applyDate < now) {
      alert('適用日時は現在日時以降を指定してください');
      return false;
    }

    if (retentionDays <= 0) {
      alert('保持期間は1日以上を設定してください');
      return false;
    }

    if (retentionDays === 0) {
      alert('保持期間に0日が設定されています。1日以上を設定してください');
      return false;
    }

    if (currentApplyProcess) {
      alert('既に適用処理が実行中です。処理完了後に再度実行してください。');
      return false;
    }

    return true;
  }

  // 適用実行
  async function executeApply(isBatch) {
    if (currentApplyProcess) {
      alert('既に適用処理が実行中です。処理完了後に再度実行してください。');
      return;
    }

    currentApplyProcess = {
      modelId: container.querySelector('#select-model').value,
      stores: Array.from(selectedStores),
      startTime: new Date(),
      isBatch: isBatch
    };

    showProgress();

    try {
      await simulateApplyProcess();
      showApplySuccess();
      enableRollback();
    } catch (error) {
      showApplyError(error.message);
    } finally {
      currentApplyProcess = null;
    }
  }

  // 適用処理シミュレーション
  async function simulateApplyProcess() {
    const stores = Array.from(selectedStores);
    const totalSteps = stores.length + 2; // 準備 + 各店舗 + 完了
    let currentStep = 0;

    // 準備
    updateProgress(currentStep++, totalSteps, '適用準備中...');
    addLog('適用処理を開始します');
    addLog(`対象モデル: ${currentModelDetails.name}`);
    addLog(`対象店舗数: ${stores.length}店舗`);

    await sleep(1000);

    // 各店舗への適用
    for (let i = 0; i < stores.length; i++) {
      const storeId = stores[i];
      updateProgress(currentStep++, totalSteps, `店舗 ${i + 1}/${stores.length} 適用中...`);
      addLog(`店舗ID: ${storeId} への適用を開始`);

      await sleep(500);

      addLog(`店舗ID: ${storeId} への適用が完了`);
    }

    // 完了
    updateProgress(currentStep++, totalSteps, '適用完了');
    addLog('全店舗への適用が正常に完了しました');
  }

  // 進捗表示
  function showProgress() {
    container.querySelector('#progress-section').style.display = 'block';
    container.querySelector('#result-log-section').style.display = 'block';
    container.querySelector('#result-log').innerHTML = '';
  }

  // 進捗更新
  function updateProgress(current, total, message) {
    const percentage = Math.round((current / total) * 100);
    container.querySelector('#progress-bar').style.width = `${percentage}%`;
    container.querySelector('#progress-text').textContent = `${message} (${percentage}%)`;
  }

  // ログ追加
  function addLog(message) {
    const logDiv = container.querySelector('#result-log');
    const timestamp = new Date().toLocaleTimeString();
    logDiv.innerHTML += `[${timestamp}] ${message}\n`;
    logDiv.scrollTop = logDiv.scrollHeight;
  }

  // 適用成功
  function showApplySuccess() {
    addLog('=== 適用処理が正常に完了しました ===');
    alert(`モデルの本番適用が完了しました。${selectedStores.size}店舗に正常に適用されました。`);
  }

  // 適用エラー
  function showApplyError(message) {
    addLog(`エラー: ${message}`);
    alert(`適用処理中にエラーが発生しました: ${message}`);
  }

  // ロールバック有効化
  function enableRollback() {
    container.querySelector('#btn-rollback').disabled = false;
  }

  // ロールバック実行
  function onRollbackClick() {
    if (!currentApplyProcess && !container.querySelector('#btn-rollback').disabled) {
      showConfirmDialog(
        'ロールバック確認',
        '現在のモデルを以前のバージョンにロールバックします。よろしいですか？',
        executeRollback
      );
    } else {
      alert('適用前のため、ロールバックできません');
    }
  }

  // ロールバック実行
  async function executeRollback() {
    showProgress();
    updateProgress(0, 3, 'ロールバック準備中...');
    addLog('ロールバック処理を開始します');

    await sleep(1000);

    updateProgress(1, 3, 'バックアップから復元中...');
    addLog('バックアップデータから復元しています');

    await sleep(2000);

    updateProgress(2, 3, 'ロールバック完了');
    addLog('ロールバック処理が正常に完了しました');

    updateProgress(3, 3, 'ロールバック完了');
    addLog('=== ロールバック処理が正常に完了しました ===');

    alert('ロールバック処理が正常に完了しました。以前のモデルバージョンが本番環境に適用されています。');

    container.querySelector('#btn-rollback').disabled = true;
  }

  // 確認ダイアログ表示
  function showConfirmDialog(title, message, onConfirm) {
    container.querySelector('#dialog-title').textContent = title;
    container.querySelector('#dialog-message').textContent = message;
    container.querySelector('#confirm-dialog').style.display = 'block';

    container.querySelector('#dialog-ok').onclick = () => {
      hideDialog();
      onConfirm();
    };
  }

  // ダイアログ非表示
  function hideDialog() {
    container.querySelector('#confirm-dialog').style.display = 'none';
  }

  // ダイアログOK
  function onDialogOk() {
    // イベントリスナーで処理
  }

  // スリープ関数
  function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  // 初期化実行
  init();
}
